import re

DIG_FROM_LETTER = {'O': '0', 'o': '0', 'D': '0', 'Q': '0', 'l': '1', 'I': '1', 'i': '1', '|': '1',
                   'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6', 'b': '6'}
LET_FROM_DIGIT = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
CONF = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50', '7': '12', '8': '30', '9': '43'}
DEFAULT_ORDER = ['CODE', 'QTY', 'UNIT', 'AMOUNT']


def _digitize(s):
    return ''.join(DIG_FROM_LETTER.get(c, c) for c in s)


def _dist(true, obs):
    # weighted edit distance: cost of turning the true digit string into the observed one
    n, m = len(true), len(obs)
    INF = 10 ** 6
    d = [[INF] * (m + 1) for _ in range(n + 1)]
    d[0][0] = 0
    for i in range(n + 1):
        for j in range(m + 1):
            v = d[i][j]
            if v >= INF:
                continue
            if i < n and j < m:
                t, o = true[i], obs[j]
                c = 0 if t == o else (1 if o in CONF.get(t, '') else 3)
                if v + c < d[i + 1][j + 1]:
                    d[i + 1][j + 1] = v + c
            if i < n and v + 1 < d[i + 1][j]:
                d[i + 1][j] = v + 1  # true digit lost
            if j < m:
                o = obs[j]
                dbl = (j > 0 and obs[j - 1] == o) or (j + 1 < m and obs[j + 1] == o)
                c = 1 if dbl else 3
                if v + c < d[i][j + 1]:
                    d[i][j + 1] = v + c
    return d[n][m]


def _check_ok(letters, digs):
    if len(digs) != 5 or len(letters) != 2 or not digs.isdigit():
        return False
    p1 = ord(letters[0]) - 64
    p2 = ord(letters[1]) - 64
    if not (1 <= p1 <= 26 and 1 <= p2 <= 26):
        return False
    s = sum((k + 1) * int(digs[k]) for k in range(4)) + p1 + p2
    return s % 10 == int(digs[4])


# ---------------- pass 1: style inference ----------------
def infer_style(state, params):
    text = state.get('input', {}).get('text', '') or ''
    lines = text.split('\n')
    sep = None
    order = list(DEFAULT_ORDER)
    for ln in lines:
        if ln.strip().startswith('COLUMNS'):
            body = ln.split('COLUMNS', 1)[1].lstrip(':').strip(' ')
            if '\t' in ln:
                sep = 'tab'
            elif '|' in ln:
                sep = 'pipe'
            elif ';' in ln:
                sep = 'semi'
            elif '   ' in body:
                sep = 'space'
            pos = [(ln.find(nm), nm) for nm in DEFAULT_ORDER]
            if all(p >= 0 for p, _ in pos):
                order = [nm for _, nm in sorted(pos)]
            break
    if sep is None:
        votes = {'tab': 0, 'pipe': 0, 'semi': 0, 'space': 0}
        for ln in lines:
            votes['tab'] += ln.count('\t')
            votes['pipe'] += ln.count('|')
            votes['semi'] += ln.count(';')
            votes['space'] += len(re.findall(r'\S {3,}\S', ln))
        sep = max(sorted(votes), key=lambda k: votes[k])
    dot = len(re.findall(r'\d\.\d\d(?!\d)', text))
    com = len(re.findall(r'\d,\d\d(?!\d)', text))
    dec = ',' if com > dot else '.'
    state['style'] = {'sep': sep, 'order': order, 'dec': dec, 'grp': "'" in text,
                      'pcs': text.count('pcs') >= 1}
    return state


# ---------------- pass 2: layout reconstruction ----------------
def _split(line, sep):
    if sep == 'tab':
        parts = line.split('\t')
    elif sep == 'pipe':
        parts = line.split('|')
    elif sep == 'semi':
        parts = line.split(';')
    else:
        parts = re.split(r' {3,}|\t', line)
    return [p.strip() for p in parts if p.strip() != '']


def _plausible(tok):
    t = re.sub(r'\s*pcs$', '', tok)
    if t == '' or len(t) > 16:
        return False
    if not re.match(r"^[0-9A-Za-z.,']+$", t):
        return False
    letters = [c for c in t if c.isalpha()]
    bad = [c for c in letters if c not in DIG_FROM_LETTER]
    if bad:
        if len(bad) > 2 or not re.match(r'^[A-Z0-9]{2}[0-9A-Za-z]{3,7}$', t):
            return False
        if any(c not in t[:2] for c in bad):
            return False
    return any(c.isdigit() or c in DIG_FROM_LETTER for c in t)


def _codelike(tok):
    if not re.match(r'^[A-Z0-9]{2}[0-9OoDQlIiSsBZzGb]{3,7}$', tok):
        return False
    return tok[0].isalpha() or tok[1].isalpha()


def rebuild_rows(state, params):
    st = state['style']
    sep = st['sep']
    ci = st['order'].index('CODE')
    lines = (state.get('input', {}).get('text', '') or '').split('\n')
    sections = []
    cur = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if re.match(r'^=+\s*SECTION', s):
            cur = {'tokens': []}
            sections.append(cur)
            continue
        if s.startswith('SUBTOTAL') or s.startswith('TOTAL'):
            continue
        toks = _split(ln, sep)
        if not toks or not all(_plausible(t) for t in toks):
            continue
        if cur is None:
            cur = {'tokens': []}
            sections.append(cur)
        cur['tokens'].extend(toks)
    rows = []
    for sec in sections:
        toks = sec['tokens']
        n = len(toks)
        if n % 4 == 0 and all(_codelike(toks[k + ci]) for k in range(0, n, 4)):
            for k in range(0, n, 4):
                rows.append(toks[k:k + 4])
            continue
        anchors = [k for k in range(n) if _codelike(toks[k])]
        if not anchors:
            for k in range(0, n - 3, 4):
                rows.append(toks[k:k + 4])
            continue
        used_to = 0
        for a in anchors:
            start = a - ci
            if start < used_to or start < 0:
                continue
            if start + 4 > n:
                rows.append(toks[start:n] + [''] * (start + 4 - n))
                used_to = n
                break
            rows.append(toks[start:start + 4])
            used_to = start + 4
    state['rows'] = rows
    return state


# ---------------- pass 3: field normalization ----------------
def _norm_code(tok):
    t = tok.strip()
    head = t[:2]
    letters = ''.join(LET_FROM_DIGIT.get(c, c) for c in head).upper()
    digs = re.sub(r'\D', '', _digitize(t[2:]))
    return letters, digs


def _norm_qty(tok):
    t = re.sub(r'\s*p\s*c\s*s\s*$', '', tok.strip())
    return re.sub(r'\D', '', _digitize(t))


def _norm_money(tok, dec):
    t = _digitize(tok.strip())
    t = re.sub(r"[^0-9.,]", '', t)
    other = ',' if dec == '.' else '.'
    t = t.replace(other, '')
    digs = t.replace(dec, '')
    if digs == '':
        return '', None
    if t.count(dec) == 1:
        ip, fp = t.split(dec)
        if len(fp) == 0:
            fp = '00'
        elif len(fp) == 1:
            fp = fp + '0'
        elif len(fp) > 2:
            fp = fp[:2]
        cents = int(ip or '0') * 100 + int(fp)
    else:
        cents = int(digs)  # decimal mark lost: last two digits are the cents
    return digs, cents


def normalize_fields(state, params):
    st = state['style']
    order = st['order']
    out = []
    for row in state['rows']:
        f = {order[i]: (row[i] if i < len(row) else '') for i in range(4)}
        letters, cdigs = _norm_code(f['CODE'])
        qd = _norm_qty(f['QTY'])
        ud, uc = _norm_money(f['UNIT'], st['dec'])
        ad, ac = _norm_money(f['AMOUNT'], st['dec'])
        out.append({'letters': letters, 'cdigs': cdigs, 'qd': qd, 'q': int(qd) if qd else None,
                    'ud': ud, 'u': uc, 'ad': ad, 'a': ac})
    state['norm'] = out
    return state


# ---------------- pass 4: code check-digit repair ----------------
def _repair_code(letters, digs):
    letters = (letters + 'AA')[:2]
    letters = ''.join(c if 'A' <= c <= 'Z' else 'A' for c in letters)
    if _check_ok(letters, digs):
        return letters + digs
    cands = []
    L = len(digs)
    if L == 5:
        for i in range(5):
            for c in '0123456789':
                if c != digs[i]:
                    cand = digs[:i] + c + digs[i + 1:]
                    if _check_ok(letters, cand):
                        cands.append(cand)
    elif L == 4:
        for i in range(5):
            for c in '0123456789':
                cand = digs[:i] + c + digs[i:]
                if _check_ok(letters, cand):
                    cands.append(cand)
    elif L == 6:
        for i in range(6):
            cand = digs[:i] + digs[i + 1:]
            if _check_ok(letters, cand):
                cands.append(cand)
    elif L > 6:
        cands.append(digs[:5])
    if not cands:
        if L >= 5:
            return letters + digs[:5]
        return letters + (digs + '00000')[:5]
    best = min(sorted(set(cands)), key=lambda c: _dist(c, digs))
    return letters + best


def repair_codes(state, params):
    for r in state['norm']:
        r['code'] = _repair_code(r['letters'], r['cdigs'])
    return state


# ---------------- pass 5: arithmetic repair ----------------
def _mdig(c):
    return str(c).rjust(3, '0')


def repair_arith(state, params):
    items = []
    for r in state['norm']:
        q, u, a = r['q'], r['u'], r['a']
        if q is not None and u is not None and a is not None and q * u == a and 1 <= q <= 500:
            items.append({'code': r['code'], 'qty': q, 'unit_cents': u})
            continue
        hyps = []
        if q is not None and u is not None and 1 <= q <= 500 and u > 0:
            ca = _dist(_mdig(q * u), r['ad']) if r['ad'] else 2
            hyps.append((ca, 0, q, u))
        if a is not None and q is not None and 1 <= q <= 500 and a > 0 and a % q == 0:
            nu = a // q
            hyps.append((_dist(_mdig(nu), r['ud']) if r['ud'] else 2, 1, q, nu))
        if a is not None and u is not None and u > 0 and a % u == 0 and 1 <= a // u <= 500:
            nq = a // u
            hyps.append((_dist(str(nq), r['qd']) if r['qd'] else 2, 2, nq, u))
        if hyps:
            hyps.sort()
            _, _, q2, u2 = hyps[0]
        else:
            q2 = q if q is not None else 1
            u2 = u if u is not None else 0
            if not (1 <= q2 <= 500):
                s = str(q2)
                q2 = int(s[:3]) if len(s) > 3 else max(1, min(500, q2))
                if q2 > 500:
                    q2 = int(s[:2])
                q2 = max(1, q2)
            if u2 == 0 and a is not None:
                u2 = a // q2
        items.append({'code': r['code'], 'qty': int(q2), 'unit_cents': int(u2)})
    state['output'] = {'items': items}
    return state


def finalize(state, params):
    out = state.get('output')
    if not isinstance(out, dict) or not isinstance(out.get('items'), list):
        state['output'] = {'items': []}
    return state

import re

MISREAD = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50', '7': '12', '8': '30', '9': '43'}
INV = {}
for _t, _s in MISREAD.items():
    for _c in _s:
        INV.setdefault(_c, []).append(_t)
TO_DIGIT = {'O': '0', 'o': '0', 'D': '0', 'Q': '0', 'l': '1', 'I': '1', 'i': '1', 'L': '1', '|': '1',
            'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6', 'b': '6'}
TO_LETTER = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G', 'l': 'I'}
NAMES = ['CODE', 'QTY', 'UNIT', 'AMOUNT']


def _sep_kind(s):
    if '|' in s:
        return 'pipe'
    if ';' in s:
        return 'semi'
    if '\t' in s:
        return 'tab'
    return 'space'


def _split(line, kind):
    if kind == 'pipe':
        toks = line.split('|')
    elif kind == 'semi':
        toks = line.split(';')
    elif kind == 'tab':
        toks = line.split('\t')
    else:
        toks = re.split(r' {2,}|\t', line.strip())
    toks = [t.strip() for t in toks]
    if len(toks) > 1 and toks[-1] == '':
        toks = toks[:-1]
    if len(toks) > 1 and toks[0] == '':
        toks = toks[1:]
    return toks


TOK_OK = re.compile(r"^[A-Za-z0-9.,'|]{0,16}( ?pcs)?$")


def _tok_ok(t, kind):
    if not TOK_OK.match(t):
        return False
    core = re.sub(r' ?pcs$', '', t)
    if re.search(r'[a-km-z]', core.replace('pcs', '')):
        return False
    return True


def infer_style(state, params):
    text = state.get('input', {}).get('text', '') or ''
    lines = text.replace('\r', '').split('\n')
    order = None
    kind = None
    for ln in lines:
        if ln.startswith('COLUMNS') or 'COLUMNS:' in ln:
            body = ln.split('COLUMNS', 1)[1].lstrip(':').strip(' ')
            pos = []
            for nm in NAMES:
                m = re.search(r'\b' + nm + r'\b', body)
                if m:
                    pos.append((m.start(), nm, m.end()))
            pos.sort()
            if len(pos) == 4:
                order = [p[1] for p in pos]
                kind = _sep_kind(body[pos[0][2]:pos[1][0]])
            break
    if kind is None:
        votes = {'pipe': 0, 'semi': 0, 'tab': 0, 'space': 0}
        for ln in lines:
            votes['pipe'] += ln.count(' | ')
            votes['semi'] += ln.count(';')
            votes['tab'] += ln.count('\t')
            votes['space'] += ln.count('   ')
        kind = max(votes, key=lambda k: votes[k])
    if order is None:
        order = list(NAMES)
    state['style'] = {'sep': kind, 'order': order}
    return state


def _codeish(t):
    return bool(re.match(r'^[A-Z0-9][A-Z0-9][0-9OlSBZGI]{4,6}$', t))


def rebuild_rows(state, params):
    text = state.get('input', {}).get('text', '') or ''
    lines = text.replace('\r', '').split('\n')
    kind = state['style']['sep']
    order = state['style']['order']
    started = False
    stream = []
    sections = []
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if re.match(r'^=+\s*SECTION', s):
            started = True
            if stream:
                sections.append(stream)
            stream = []
            continue
        if not started:
            continue
        if re.match(r'^(SUBTOTAL|TOTAL)\b', s) or s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        toks = _split(ln, kind)
        if not toks or not all(_tok_ok(t, kind) for t in toks):
            continue
        if not any(re.search(r'[0-9]', t) for t in toks):
            continue
        stream.extend(toks)
    if stream:
        sections.append(stream)
    ci = order.index('CODE')
    rows = []
    for st in sections:
        if len(st) % 4 == 0:
            for i in range(0, len(st), 4):
                rows.append(dict(zip(order, st[i:i + 4])))
        else:
            i = 0
            while i < len(st):
                grp = st[i:i + 4]
                if len(grp) == 4 and _codeish(grp[ci]):
                    rows.append(dict(zip(order, grp)))
                    i += 4
                    continue
                found = False
                for j in range(i + 1, len(st)):
                    if j + ci < len(st) and _codeish(st[j + ci]) and j + 4 <= len(st):
                        if j - i >= 1 and len(grp) == 4:
                            part = st[i:j] + [''] * 4
                            rows.append(dict(zip(order, part[:4])))
                        i = j
                        found = True
                        break
                if not found:
                    if len(grp) >= 2:
                        part = grp + [''] * 4
                        rows.append(dict(zip(order, part[:4])))
                    break
    state['raw_rows'] = rows
    return state


def _check_ok(code):
    if len(code) != 7 or not code[:2].isalpha() or not code[2:].isdigit():
        return False
    p1 = ord(code[0]) - 64
    p2 = ord(code[1]) - 64
    d = [int(c) for c in code[2:]]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p1 + p2) % 10 == d[4]


def _check_digit(lets, d4):
    p1 = ord(lets[0]) - 64
    p2 = ord(lets[1]) - 64
    return (int(d4[0]) + 2 * int(d4[1]) + 3 * int(d4[2]) + 4 * int(d4[3]) + p1 + p2) % 10


def _fix_code(tok):
    t = tok.strip().replace(' ', '')
    if len(t) < 2:
        return 'AA00000'
    lets = ''.join(TO_LETTER.get(c, c.upper()) for c in t[:2])
    lets = ''.join(c if 'A' <= c <= 'Z' else 'A' for c in lets)
    digs = ''.join(TO_DIGIT.get(c, c) for c in t[2:])
    digs = ''.join(c for c in digs if c.isdigit())
    if len(digs) == 5:
        c = lets + digs
        if _check_ok(c):
            return c
        for i in (4, 0, 1, 2, 3):
            for alt in INV.get(digs[i], []):
                nd = digs[:i] + alt + digs[i + 1:]
                if _check_ok(lets + nd):
                    return lets + nd
        return lets + digs[:4] + str(_check_digit(lets, digs[:4]))
    if len(digs) == 6:
        for i in range(5):
            if digs[i] == digs[i + 1]:
                nd = digs[:i] + digs[i + 1:]
                if _check_ok(lets + nd):
                    return lets + nd
        nd = digs[:4]
        return lets + nd + str(_check_digit(lets, nd))
    if len(digs) == 4:
        return lets + digs + str(_check_digit(lets, digs))
    if len(digs) > 6:
        nd = digs[:4]
        return lets + nd + str(_check_digit(lets, nd))
    nd = (digs + '0000')[:4]
    return lets + nd + str(_check_digit(lets, nd))


def _digits(tok):
    t = re.sub(r' ?pcs$', '', tok.strip())
    return ''.join(c for c in (TO_DIGIT.get(ch, ch) for ch in t) if c.isdigit())


def _money_obs(tok):
    """returns (digit string, cents if format-consistent else None, best guess cents)"""
    t = tok.strip().replace("'", '')
    t = ''.join(TO_DIGIT.get(ch, ch) for ch in t)
    ds = ''.join(c for c in t if c.isdigit())
    m = re.search(r'[.,](\d*)$', t)
    if not ds:
        return ds, None, None
    if m is None:
        v = int(ds)
        return ds, v, v
    fl = len(m.group(1))
    if fl == 2:
        v = int(ds)
        return ds, v, v
    ip = t[:m.start()]
    ipd = ''.join(c for c in ip if c.isdigit()) or '0'
    fr = m.group(1)
    if fl == 3:
        g = None
        for i in range(2):
            if fr[i] == fr[i + 1]:
                g = fr[:i] + fr[i + 1:]
                break
        if g is None:
            g = fr[:2]
    elif fl == 1:
        g = fr + '0'
    else:
        g = (fr + '00')[:2]
    return ds, None, int(ipd) * 100 + int(g)


def _fmt(c):
    return str(c // 100) + '%02d' % (c % 100)


def _edit1(obs, cand):
    if obs == cand:
        return True
    lo, lc = len(obs), len(cand)
    if lo == lc:
        diff = [i for i in range(lo) if obs[i] != cand[i]]
        return len(diff) == 1 and obs[diff[0]] in MISREAD.get(cand[diff[0]], '')
    if lo == lc - 1:
        for i in range(lc):
            if cand[:i] + cand[i + 1:] == obs:
                return True
        return False
    if lo == lc + 1:
        for i in range(lc):
            if cand[:i + 1] + cand[i] + cand[i + 1:] == obs:
                return True
        return False
    return False


def _qty_guess(qd):
    if not qd:
        return None
    q = int(qd)
    if 1 <= q <= 500:
        return q
    if len(qd) >= 2:
        for i in range(len(qd) - 1):
            if qd[i] == qd[i + 1]:
                q2 = int(qd[:i] + qd[i + 1:])
                if 1 <= q2 <= 500:
                    return q2
    return q


def _fix_arith(row):
    qd = _digits(row.get('QTY', ''))
    q0 = int(qd) if qd else None
    qv = q0 if q0 is not None and 1 <= q0 <= 500 else None
    ud, uv, ug = _money_obs(row.get('UNIT', ''))
    ad, av, ag = _money_obs(row.get('AMOUNT', ''))
    if qv is not None and uv is not None and av is not None and qv * uv == av:
        return qv, uv
    if qv is not None and uv is not None and _edit1(ad, _fmt(qv * uv)):
        return qv, uv
    if qv is not None and av is not None and av % qv == 0 and _edit1(ud, _fmt(av // qv)):
        return qv, av // qv
    if uv and av is not None and av % uv == 0 and 1 <= av // uv <= 500 and _edit1(qd, str(av // uv)):
        return av // uv, uv
    if qv is not None and uv is not None:
        return qv, uv
    if uv is None and qv is not None and av is not None and av % qv == 0:
        return qv, av // qv
    if qv is None and uv and av is not None and av % uv == 0 and 1 <= av // uv <= 500:
        return av // uv, uv
    if qv is None and uv and av:
        q = int(round(av / uv))
        if 1 <= q <= 500:
            return q, uv
    q = qv if qv is not None else _qty_guess(qd)
    if q is None:
        q = 1
    u = uv if uv is not None else ug
    if u is None:
        u = ag // q if ag is not None and q else 0
    return q, u


def repair_rows(state, params):
    items = []
    for row in state.get('raw_rows', []):
        try:
            code = _fix_code(row.get('CODE', ''))
        except Exception:
            code = 'AA00000'
        try:
            q, u = _fix_arith(row)
        except Exception:
            q, u = 1, 0
        items.append({'code': code, 'qty': int(q), 'unit_cents': int(u)})
    state['output'] = {'items': items}
    return state

import re
import time

MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
       '6': '50', '7': '12', '8': '30', '9': '43'}
INV = {}
for _d, _ms in MIS.items():
    for _m in _ms:
        INV.setdefault(_m, []).append(_d)
D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
L2D = {'O': '0', 'o': '0', 'Q': '0', 'D': '0', 'l': '1', 'I': '1', 'i': '1', '|': '1',
       'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6', 'b': '6'}
DIGITS = '0123456789'

C_MIS1 = 1.0
C_MIS2 = 1.1
C_LOST = 1.0
C_DBL = 1.0
C_DEC = 0.5
C_BAD = 2.5
C_UNK = 1.5
C_LOOK = 0.2
LB_MISS = 2.0
INF = 1e18

CODE_RE = re.compile(r"^[A-Za-z0-9?]{2}[0-9OolISBZGsziQD]{2,8}$")
QTY_RE = re.compile(r"^[0-9OolISBZGszi]{1,4}(\s*pcs)?$")
MONEY_RE = re.compile(r"^[0-9OolISBZGszi']{1,12}([.,][0-9OolISBZGszi]{0,3})?$")
MONEY_OK = re.compile(r"^(0|[1-9][0-9]*)\.[0-9][0-9]$")
QTY_OK = re.compile(r"^[1-9][0-9]{0,2}$")


# ---------------------------------------------------------------- channel cost
def edit_cost(orig, obs, memo):
    key = orig + '|' + obs
    v = memo.get(key)
    if v is not None:
        return v
    m = len(obs)
    prev = [0.0] * (m + 1)
    for j in range(1, m + 1):
        prev[j] = prev[j - 1] + C_BAD
    for i in range(1, len(orig) + 1):
        oc = orig[i - 1]
        delc = C_DEC if oc == '.' else C_LOST
        mis = MIS.get(oc, '')
        misc = C_MIS1 if len(mis) == 1 else C_MIS2
        cur = [prev[0] + delc] + [0.0] * m
        for j in range(1, m + 1):
            bc = obs[j - 1]
            if bc == oc:
                s = prev[j - 1]
            elif bc in mis:
                s = prev[j - 1] + misc
            elif bc == '?' and oc != '.':
                s = prev[j - 1] + C_UNK
            else:
                s = prev[j - 1] + C_BAD
            d = prev[j] + delc
            if d < s:
                s = d
            ins = cur[j - 1] + (C_DBL if (bc == oc and oc != '.') else C_BAD)
            if ins < s:
                s = ins
            cur[j] = s
        prev = cur
    v = prev[m]
    memo[key] = v
    return v


def fmt_money(c):
    return "%d.%02d" % (c // 100, c % 100)


# ---------------------------------------------------------------- normalisation
def norm_digits(t):
    out = []
    for ch in t:
        if ch in DIGITS or ch == '.':
            out.append(ch)
        elif ch in L2D:
            out.append(L2D[ch])
        elif ch in " '":
            continue
        else:
            out.append('?')
    return ''.join(out)


def norm_money(t, dm):
    t = t.strip().replace("'", "").replace(' ', '')
    if dm == ',':
        t = t.replace('.', '').replace(',', '.')
    else:
        t = t.replace(',', '')
    return norm_digits(t)


def norm_qty(t):
    t = re.sub(r"\s*pcs\s*$", "", t.strip())
    return norm_digits(t.replace('.', '').replace(',', ''))


# ---------------------------------------------------------------- candidate gen
def neighbors(s):
    out = set()
    L = len(s)
    for k in range(L):
        ch = s[k]
        if ch == '?':
            for d in DIGITS:
                out.add(s[:k] + d + s[k + 1:])
        elif ch in INV:
            for d in INV[ch]:
                out.add(s[:k] + d + s[k + 1:])
        if k > 0 and ch == s[k - 1] and ch != '.':
            out.add(s[:k] + s[k + 1:])
    for k in range(L + 1):
        a = s[:k]
        b = s[k:]
        for d in DIGITS:
            out.add(a + d + b)
    return out


def money_cands(obs, memo):
    res = {}
    if obs is None:
        return res
    S = set([obs])
    S |= neighbors(obs)
    extra = []
    for t in S:
        if '.' not in t and len(t) >= 3:
            extra.append(t[:-2] + '.' + t[-2:])
    S.update(extra)
    for t in S:
        if len(t) <= 12 and MONEY_OK.match(t):
            c = int(t.replace('.', ''))
            if c <= 0:
                continue
            cost = edit_cost(t, obs, memo)
            if cost < res.get(c, INF):
                res[c] = cost
    return res


def qty_cands(obs, memo):
    res = {}
    if obs is None:
        return res
    S = set([obs])
    S |= neighbors(obs)
    for t in S:
        if QTY_OK.match(t):
            q = int(t)
            if 1 <= q <= 500:
                cost = edit_cost(t, obs, memo)
                if cost < res.get(q, INF):
                    res[q] = cost
    return res


def check_digit(letters, d4):
    p1 = ord(letters[0]) - 64
    p2 = ord(letters[1]) - 64
    s = int(d4[0]) + 2 * int(d4[1]) + 3 * int(d4[2]) + 4 * int(d4[3]) + p1 + p2
    return str(s % 10)


def code_decode(tok, memo):
    t = tok.strip().replace(' ', '')
    if len(t) < 2:
        t = (t + 'AA')[:2]
    lp = t[:2]
    letters = ''
    lcost = 0.0
    for ch in lp:
        c = ch.upper()
        if ch.isalpha() and 'A' <= c <= 'Z':
            letters += c
        elif ch in D2L:
            letters += D2L[ch]
            lcost += C_LOOK
        else:
            letters += 'A'
            lcost += C_BAD
    obs = norm_digits(t[2:].replace('.', ''))
    L = len(obs)
    bases = set()
    if L == 5:
        bases.add(obs)
    elif L == 4 or L == 3:
        cur = set([obs])
        for _ in range(5 - L):
            nxt = set()
            for s in cur:
                for k in range(len(s) + 1):
                    for d in DIGITS:
                        nxt.add(s[:k] + d + s[k:])
            cur = nxt
        bases = cur
    elif L == 6 or L == 7:
        cur = set([obs])
        for _ in range(L - 5):
            nxt = set()
            for s in cur:
                for k in range(len(s)):
                    nxt.add(s[:k] + s[k + 1:])
            cur = nxt
        bases = cur
    elif L > 7:
        bases.add(obs[:5])
    else:
        bases.add((obs + '00000')[:5])

    def subs1(s):
        out = []
        for k in range(5):
            ch = s[k]
            if ch == '?':
                opts = DIGITS
            else:
                opts = INV.get(ch, [])
            for d in opts:
                out.append(s[:k] + d + s[k + 1:])
        return out

    def valid(s):
        return '?' not in s and check_digit(letters, s[:4]) == s[4]

    best = None
    level = list(bases)
    seen = set()
    for depth in range(3):
        found = []
        for s in level:
            if s in seen:
                continue
            seen.add(s)
            if valid(s):
                found.append(s)
        if found:
            for s in found:
                c = edit_cost(s, obs, memo)
                if best is None or c < best[0] or (c == best[0] and s < best[1]):
                    best = (c, s)
            break
        if depth == 2:
            break
        nxt = set()
        for s in level:
            for x in subs1(s):
                nxt.add(x)
        level = list(nxt)
    if best is None:
        s = ''.join(ch if ch in DIGITS else '0' for ch in (obs + '0000')[:4])
        return letters + s + check_digit(letters, s), INF
    return letters + best[1], best[0] + lcost


# ---------------------------------------------------------------- row lattice
def solve_row(qo, uo, ao, memo, margin, deadline):
    Q = qty_cands(qo, memo)
    U = money_cands(uo, memo)
    A = money_cands(ao, memo)
    Ql = sorted(Q.items(), key=lambda x: (x[1], x[0]))
    Ul = sorted(U.items(), key=lambda x: (x[1], x[0]))
    Al = sorted(A.items(), key=lambda x: (x[1], x[0]))
    res = {}
    best = [INF]

    def rec(q, u, c):
        k = (q, u)
        if c < res.get(k, INF):
            res[k] = c
        if c < best[0]:
            best[0] = c

    if Ql and Ul and Al and Ql[0][1] == 0 and Ul[0][1] == 0 and Al[0][1] == 0:
        if Ql[0][0] * Ul[0][0] == Al[0][0]:
            rec(Ql[0][0], Ul[0][0], 0.0)
    timed_out = False
    # (q,u) -> a
    for q, cq in Ql:
        if cq > best[0] + margin:
            break
        for u, cu in Ul:
            s = cq + cu
            if s > best[0] + margin:
                break
            a = q * u
            ca = A.get(a)
            if ca is None:
                if s + LB_MISS > best[0] + margin or ao is None:
                    continue
                ca = edit_cost(fmt_money(a), ao, memo)
            rec(q, u, s + ca)
        if time.perf_counter() > deadline:
            timed_out = True
            break
    # (q,a) -> u
    if not timed_out:
        for q, cq in Ql:
            if cq > best[0] + margin:
                break
            for a, ca in Al:
                s = cq + ca
                if s > best[0] + margin:
                    break
                if a % q:
                    continue
                u = a // q
                cu = U.get(u)
                if cu is None:
                    if s + LB_MISS > best[0] + margin or uo is None:
                        continue
                    cu = edit_cost(fmt_money(u), uo, memo)
                rec(q, u, s + cu)
            if time.perf_counter() > deadline:
                timed_out = True
                break
    # (u,a) -> q
    if not timed_out:
        for u, cu in Ul:
            if cu > best[0] + margin:
                break
            for a, ca in Al:
                s = cu + ca
                if s > best[0] + margin:
                    break
                if a % u:
                    continue
                q = a // u
                if q < 1 or q > 500:
                    continue
                cq = Q.get(q)
                if cq is None:
                    if s + LB_MISS > best[0] + margin or qo is None:
                        continue
                    cq = edit_cost(str(q), qo, memo)
                rec(q, u, s + cq)
            if time.perf_counter() > deadline:
                break
    alts = sorted(((c, q, u) for (q, u), c in res.items()), key=lambda x: (x[0], x[1], x[2]))
    alts = [a for a in alts if a[0] <= best[0] + margin][:8]
    if not alts:
        q = Ql[0][0] if Ql else 1
        u = Ul[0][0] if Ul else (Al[0][0] // q if Al else 0)
        alts = [(50.0, q, u)]
    return [[c, q, u, q * u] for c, q, u in alts]


# ---------------------------------------------------------------- layout
def sep_regex(sep):
    if '|' in sep:
        return r"\s*\|\s*"
    if ';' in sep:
        return r"\s*;\s*"
    if '\t' in sep:
        return r"\s*\t\s*"
    return r" {2,}|\t"


def tok_cost(t, typ):
    has_pcs = 'pcs' in t
    if typ == 'CODE':
        if has_pcs:
            return 5.0
        if CODE_RE.match(t) and '.' not in t and ',' not in t:
            alpha = sum(1 for ch in t[:2] if ch.isalpha())
            return 0.0 if alpha >= 1 else 0.8
        if 5 <= len(t) <= 10 and any(ch.isalpha() for ch in t[:2]):
            return 2.0
        return 4.0
    if typ == 'QTY':
        if QTY_RE.match(t):
            return 0.0 if len(t.replace('pcs', '').strip()) <= 3 else 1.0
        return 4.0
    if has_pcs:
        return 5.0
    if MONEY_RE.match(t):
        if '.' in t or ',' in t:
            return 0.0
        n = len(t.replace("'", ''))
        if n >= 3:
            return 1.0 if n <= 6 else 1.5
        return 2.5
    return 4.0


def layout_rows(tokens, cols):
    n = len(tokens)
    tc = [[tok_cost(t, c) for c in cols] for t in tokens]
    f = [INF] * (n + 1)
    back = [None] * (n + 1)
    f[0] = 0.0
    for i in range(n):
        if f[i] >= INF:
            continue
        c = f[i] + 6.0
        if c < f[i + 1]:
            f[i + 1] = c
            back[i + 1] = ('skip', i, -1)
        if i + 4 <= n:
            c = f[i] + tc[i][0] + tc[i + 1][1] + tc[i + 2][2] + tc[i + 3][3]
            if c < f[i + 4]:
                f[i + 4] = c
                back[i + 4] = ('row', i, -1)
        if i + 3 <= n:
            for miss in range(4):
                c = f[i] + 5.0
                k = i
                for col in range(4):
                    if col == miss:
                        continue
                    c += tc[k][col]
                    k += 1
                if c < f[i + 3]:
                    f[i + 3] = c
                    back[i + 3] = ('row', i, miss)
    rows = []
    j = n
    while j > 0:
        b = back[j]
        if b is None:
            break
        if b[0] == 'skip':
            j = b[1]
            continue
        i, miss = b[1], b[2]
        fields = []
        k = i
        for col in range(4):
            if col == miss:
                fields.append(None)
            else:
                fields.append(tokens[k])
                k += 1
        rows.append(fields)
        j = i
    rows.reverse()
    return rows


def parse_layout(state, params):
    text = (state.get("input") or {}).get("text", "") or ""
    lines = text.replace('\r', '').split('\n')
    cols = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sep = ';'
    for ln in lines:
        if ln.lstrip().startswith('COLUMNS'):
            body = ln.split(':', 1)[1] if ':' in ln else ln.lstrip()[7:]
            pos = []
            for name in ['CODE', 'QTY', 'UNIT', 'AMOUNT']:
                p = body.find(name)
                if p >= 0:
                    pos.append((p, name))
            pos.sort()
            if len(pos) == 4:
                cols = [nm for _, nm in pos]
                sep = body[pos[0][0] + len(pos[0][1]):pos[1][0]]
            break
    srx = re.compile(sep_regex(sep))
    sections = []
    total_raw = None
    items_raw = None
    cur = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if re.match(r"^=+\s*SECTION\b", s):
            cur = {"tokens": [], "sub": None}
            sections.append(cur)
            continue
        if s.startswith('SUBTOTAL'):
            if cur is not None:
                cur["sub"] = s[8:].strip()
                cur = None
            continue
        if s.startswith('TOTAL'):
            m = re.match(r"TOTAL\s*(.*?)\s*ITEMS\s*(.*)$", s)
            if m:
                total_raw = m.group(1)
                items_raw = m.group(2)
            else:
                total_raw = s[5:].strip()
            cur = None
            continue
        if 'page' in s.lower() or re.search(r"-{2,}|\*{2,}|#{2,}", s):
            continue
        toks = [t.strip() for t in srx.split(ln) if t.strip()]
        if not toks:
            continue
        if not any(min(tok_cost(t, c) for c in cols) < 3 for t in toks):
            continue
        if cur is None:
            if sections and sections[-1]["sub"] is None:
                cur = sections[-1]
            else:
                cur = {"tokens": [], "sub": None}
                sections.append(cur)
        cur["tokens"].extend(toks)
    dot = 0
    com = 0
    probe = []
    for sec in sections:
        probe.extend(sec["tokens"])
        if sec["sub"]:
            probe.append(sec["sub"])
    if total_raw:
        probe.append(total_raw)
    for t in probe:
        if re.search(r"\.[0-9OlSBZG]{2}$", t):
            dot += 1
        elif re.search(r",[0-9OlSBZG]{2}$", t):
            com += 1
    dm = ',' if com > dot else '.'
    out_secs = []
    for sec in sections:
        rows = layout_rows(sec["tokens"], cols)
        orows = []
        for fields in rows:
            d = {}
            for col, val in zip(cols, fields):
                d[col] = val
            orows.append({
                "code": d['CODE'],
                "qty": norm_qty(d['QTY']) if d['QTY'] is not None else None,
                "unit": norm_money(d['UNIT'], dm) if d['UNIT'] is not None else None,
                "amount": norm_money(d['AMOUNT'], dm) if d['AMOUNT'] is not None else None,
            })
        out_secs.append({"rows": orows,
                         "sub": norm_money(sec["sub"], dm) if sec["sub"] else None})
    state["layout"] = {"sections": out_secs,
                       "total": norm_money(total_raw, dm) if total_raw else None,
                       "items": items_raw}
    return state


# ---------------------------------------------------------------- decode rows
def decode_rows(state, params):
    t0 = time.perf_counter()
    lay = state.get("layout") or {"sections": []}
    memo = {}
    nrows = sum(len(s["rows"]) for s in lay["sections"]) or 1
    hard_deadline = t0 + 0.70
    done = 0
    for sec in lay["sections"]:
        for r in sec["rows"]:
            now = time.perf_counter()
            remaining = hard_deadline - now
            left = nrows - done
            per = max(remaining / max(left, 1), 0.0)
            margin = 1.0 if per > 0.004 else 0.0
            code_tok = r["code"]
            if code_tok is None:
                r["code_out"] = "AA00002"
            else:
                r["code_out"] = code_decode(code_tok, memo)[0]
            if remaining <= 0:
                Q = qty_cands(r["qty"], memo) if r["qty"] else {}
                U = money_cands(r["unit"], memo) if r["unit"] else {}
                q = min(Q.items(), key=lambda x: (x[1], x[0]))[0] if Q else 1
                u = min(U.items(), key=lambda x: (x[1], x[0]))[0] if U else 0
                r["alts"] = [[50.0, q, u, q * u]]
            else:
                r["alts"] = solve_row(r["qty"], r["unit"], r["amount"], memo,
                                      margin, now + max(per * 3, 0.002))
            done += 1
    state["layout"] = lay
    return state


# ---------------------------------------------------------------- sum repair
def sum_fix(state, params):
    lay = state.get("layout") or {"sections": []}
    memo = {}
    allrows = []
    cons = []
    for sec in lay["sections"]:
        idx = []
        for r in sec["rows"]:
            r["sel"] = 0
            idx.append(len(allrows))
            allrows.append(r)
        if sec.get("sub") and idx:
            cons.append([sec["sub"], idx])
    if lay.get("total") and allrows:
        cons.append([lay["total"], list(range(len(allrows)))])
    row_cons = [[] for _ in allrows]
    for ci, c in enumerate(cons):
        for i in c[1]:
            row_cons[i].append(ci)

    def csum(ci):
        return sum(allrows[i]["alts"][allrows[i]["sel"]][3] for i in cons[ci][1])

    def ccost(S, ci):
        if S <= 0:
            return C_BAD * 4
        return edit_cost(fmt_money(S), cons[ci][0], memo)

    t0 = time.perf_counter()
    for _ in range(8):
        if time.perf_counter() - t0 > 0.1:
            break
        sums = [csum(ci) for ci in range(len(cons))]
        costs = [ccost(sums[ci], ci) for ci in range(len(cons))]
        if all(c == 0 for c in costs):
            break
        best = None
        for ri, r in enumerate(allrows):
            if len(r["alts"]) < 2 or not row_cons[ri]:
                continue
            if all(costs[ci] == 0 for ci in row_cons[ri]):
                continue
            cur = r["alts"][r["sel"]]
            for ai, alt in enumerate(r["alts"]):
                if ai == r["sel"] or alt[3] == cur[3]:
                    continue
                d = alt[0] - cur[0]
                for ci in row_cons[ri]:
                    d += ccost(sums[ci] - cur[3] + alt[3], ci) - costs[ci]
                if d < -0.05 and (best is None or d < best[0]):
                    best = (d, ri, ai)
        if best is None:
            break
        allrows[best[1]]["sel"] = best[2]
    items = []
    for r in allrows:
        a = r["alts"][r["sel"]]
        items.append({"code": r.get("code_out") or "AA00002", "qty": int(a[1]),
                      "unit_cents": int(a[2])})
    state["output"] = {"items": items}
    return state

import re
import time

LOOK = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'S': '5', 'B': '8', 'Z': '2', 'G': '6'}
DIG2LET = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
MIS_INV = {'6': '05', '8': '03', '7': '12', '4': '19', '9': '34', '1': '47',
           '3': '589', '0': '68', '5': '6', '2': '7'}
C_MIS = 1.0
C_DUP = 1.0
C_INS = 1.15
C_LOOK = 0.05
C_MARK = 0.3
COLS = ['CODE', 'QTY', 'UNIT', 'AMOUNT']


def _gen(seq, maxops, max_ins=1):
    """Inverse channel. seq: list of observed chars (digits, fixed markers '.' and "'",
    '?' for unknown). Returns dict original_string -> (cost, ops)."""
    out = {}
    n = len(seq)

    def rec(i, prefix, cost, ops, ins):
        if ops < maxops and ins < max_ins:
            for d in '0123456789':
                rec2(i, prefix + d, cost + C_INS, ops + 1, ins + 1)
        rec2(i, prefix, cost, ops, ins)

    def rec2(i, prefix, cost, ops, ins):
        if i == n:
            old = out.get(prefix)
            if old is None or cost < old[0]:
                out[prefix] = (cost, ops)
            return
        c = seq[i]
        if c == '.' or c == "'":
            rec(i + 1, prefix + c, cost, ops, ins)
            return
        if c == '?':
            if ops < maxops:
                for d in '0123456789':
                    rec(i + 1, prefix + d, cost + C_MIS, ops + 1, ins)
                rec(i + 1, prefix, cost + C_MIS, ops + 1, ins)
            return
        if ops < maxops and i > 0 and seq[i - 1] == c:
            rec(i + 1, prefix, cost + C_DUP, ops + 1, ins)
        rec(i + 1, prefix + c, cost, ops, ins)
        if ops < maxops:
            for t in MIS_INV.get(c, ''):
                rec(i + 1, prefix + t, cost + C_MIS, ops + 1, ins)

    rec(0, '', 0.0, 0, 0)
    return out


def _digit_seq(s, keep):
    seq = []
    extra = 0.0
    for ch in s:
        if ch.isdigit():
            seq.append(ch)
        elif ch in keep:
            seq.append(ch)
        elif ch in LOOK:
            seq.append(LOOK[ch])
            extra += C_LOOK
        elif ch.isspace():
            continue
        else:
            seq.append('?')
    return seq, extra


def money_cands(tok, style, maxops):
    dm = style['dm']
    grouping = style['group']
    s = tok.strip()
    seq, extra = _digit_seq(s, (dm, "'"))
    seq = ['.' if c == dm else c for c in seq]
    if seq.count('.') > 1:
        last = len(seq) - 1 - seq[::-1].index('.')
        seq = [c for k, c in enumerate(seq) if c != '.' or k == last]
    has_mark = '.' in seq
    raw = _gen(seq, maxops)
    res = {}
    for st, (cost, ops) in raw.items():
        cost += extra
        if has_mark:
            ip, fp = st.split('.')
            if len(fp) != 2 or "'" in fp:
                continue
        else:
            d = st.replace("'", '')
            if len(d) < 3:
                continue
            k = len(st)
            cnt = 0
            while k > 0 and cnt < 2:
                k -= 1
                if st[k] == "'":
                    cnt = -99
                    break
                cnt += 1
            if cnt < 2:
                continue
            ip, fp = st[:k], st[k:]
            cost += C_MARK
        idig = ip.replace("'", '')
        if idig == '' or (len(idig) > 1 and idig[0] == '0'):
            continue
        if grouping:
            groups = ip.split("'")
            okg = True
            if len(idig) >= 4 and len(groups) == 1:
                okg = False
            if len(groups) > 1:
                if not (1 <= len(groups[0]) <= 3):
                    okg = False
                for g in groups[1:]:
                    if len(g) != 3:
                        okg = False
            if not okg:
                cost += 3.0
        elif "'" in ip:
            cost += 3.0
        v = int(idig) * 100 + int(fp)
        if v <= 0:
            continue
        old = res.get(v)
        if old is None or cost < old[0]:
            res[v] = (cost, ops)
    return res


def qty_cands(tok, maxops):
    s = tok.strip()
    s = re.sub(r'\s*pcs\s*$', '', s)
    seq, extra = _digit_seq(s, ())
    raw = _gen(seq, maxops)
    res = {}
    for st, (cost, ops) in raw.items():
        if st == '' or (len(st) > 1 and st[0] == '0') or len(st) > 3:
            continue
        v = int(st)
        if v < 1 or v > 500:
            continue
        cost += extra
        old = res.get(v)
        if old is None or cost < old[0]:
            res[v] = (cost, ops)
    return res


def code_ok(code):
    p1 = ord(code[0]) - 64
    p2 = ord(code[1]) - 64
    d = [int(c) for c in code[2:]]
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p1 + p2) % 10 == d[4]


def best_code(tok):
    s = re.sub(r'\s', '', tok)
    if len(s) < 2:
        s = (s + 'AA')[:2]
    letter_opts = []
    for ch in s[:2]:
        if 'A' <= ch <= 'Z':
            letter_opts.append([(ch, 0.0)])
        elif ch in DIG2LET:
            letter_opts.append([(DIG2LET[ch], C_LOOK)])
        elif ch == 'l':
            letter_opts.append([('I', C_LOOK)])
        elif 'a' <= ch <= 'z':
            letter_opts.append([(ch.upper(), 0.5)])
        else:
            letter_opts.append([(chr(65 + k), 2.0) for k in range(26)])
    unknown_letter = any(len(o) > 1 for o in letter_opts)
    seq, extra = _digit_seq(s[2:], ())
    best = None
    for maxops in (0, 1, 2):
        if maxops == 2 and unknown_letter:
            break
        raw = _gen(seq, maxops)
        for st, (cost, ops) in raw.items():
            if len(st) != 5:
                continue
            for l1, c1 in letter_opts[0]:
                for l2, c2 in letter_opts[1]:
                    code = l1 + l2 + st
                    if code_ok(code):
                        tc = cost + c1 + c2 + extra
                        if best is None or tc < best[0] or (tc == best[0] and code < best[1]):
                            best = (tc, code)
        if best is not None:
            return best[1]
    st = ''.join(c if c.isdigit() else '0' for c in seq)[:5].ljust(5, '0')
    l1 = letter_opts[0][0][0]
    l2 = letter_opts[1][0][0]
    p = ord(l1) - 64 + ord(l2) - 64
    d = [int(c) for c in st]
    ck = (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p) % 10
    return l1 + l2 + st[:4] + str(ck)


# ---------------------------------------------------------------- layout pass

def _split_line(line, sep):
    if sep in ('|', ';'):
        parts = line.split(sep)
    else:
        parts = re.split(r'\t| {2,}', line)
    return [p.strip() for p in parts if p.strip() != '']


FIELDISH = re.compile(r"[0-9A-Z.,'l]+(\s*pcs)?")


def node_layout(state, params):
    text = (state.get('input') or {}).get('text', '') or ''
    lines = text.split('\n')
    order = list(COLS)
    sep = None
    for ln in lines:
        s = ln.strip()
        if s.startswith('COLUMNS'):
            body = ln.split(':', 1)[1] if ':' in ln else ln[7:]
            pos = []
            for c in COLS:
                m = re.search(r'\b' + c + r'\b', body)
                if m:
                    pos.append((m.start(), m.end(), c))
            pos.sort()
            if len(pos) == 4:
                order = [p[2] for p in pos]
                between = body[pos[0][1]:pos[1][0]]
                if '|' in between:
                    sep = '|'
                elif ';' in between:
                    sep = ';'
                elif '\t' in between:
                    sep = '\t'
                else:
                    sep = '   '
            break
    if sep is None:
        cnt = {'|': text.count('|'), ';': text.count(';'), '\t': text.count('\t'),
               '   ': text.count('   ')}
        sep = max(sorted(cnt), key=lambda k: cnt[k])
        if cnt[sep] == 0:
            sep = '   '
    sections = []
    cur = None
    total_tok = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if re.match(r'^=+\s*SECTION', s):
            cur = {'tokens': [], 'subtotal': None}
            sections.append(cur)
            continue
        if s.startswith('SUBTOTAL'):
            if cur is not None:
                cur['subtotal'] = s[len('SUBTOTAL'):].strip()
            continue
        if s.startswith('TOTAL'):
            m = re.match(r'TOTAL\s+(.*?)\s+ITEMS', s)
            if m:
                total_tok = m.group(1)
            continue
        toks = _split_line(ln, sep)
        good = [t for t in toks if FIELDISH.fullmatch(t)]
        if not good:
            continue
        if cur is None:
            cur = {'tokens': [], 'subtotal': None}
            sections.append(cur)
        cur['tokens'].extend(good)
    alltoks = []
    for sec in sections:
        alltoks.extend(sec['tokens'])
        if sec['subtotal']:
            alltoks.append(sec['subtotal'])
    dot = sum(1 for t in alltoks if re.search(r'\.[0-9OlSBZG]{2}$', t))
    com = sum(1 for t in alltoks if re.search(r',[0-9OlSBZG]{2}$', t))
    dm = ',' if com > dot else '.'
    grouping = any("'" in t for t in alltoks)
    pcs = any('pcs' in t for t in alltoks)
    style = {'dm': dm, 'group': grouping, 'pcs': pcs}
    out_secs = []
    for sec in sections:
        out_secs.append({'rows': _align(sec['tokens'], order, pcs), 'subtotal': sec['subtotal']})
    state['layout'] = {'sections': out_secs, 'order': order, 'style': style, 'total': total_tok}
    return state


def _fit(tok, col, pcs):
    if col == 'CODE':
        if re.fullmatch(r"[A-Z0-9l]{2}[0-9OlSBZGI]{4,6}", tok):
            return 0.0
        if re.fullmatch(r"[A-Z0-9l]{5,9}", tok) and re.search(r'[A-Z]', tok):
            return 1.0
        return 3.0
    if col == 'QTY':
        has = 'pcs' in tok
        core = re.sub(r'\s*pcs$', '', tok)
        c = 0.0 if re.fullmatch(r"[0-9OlSBZG]{1,4}", core) else 3.0
        if pcs and not has:
            c += 2.0
        if (not pcs) and has:
            c += 2.0
        return c
    c = 0.0 if (re.fullmatch(r"[0-9OlSBZG'.,]{2,}", tok) and re.search(r'[0-9]', tok)) else 3.0
    if 'pcs' in tok:
        c += 3.0
    if re.fullmatch(r"[A-Z]{2}.*", tok):
        c += 1.5
    return c


def _align(tokens, order, pcs):
    n = len(tokens)
    INF = float('inf')
    SKIP = 4.0
    dp = [[INF] * 4 for _ in range(n + 1)]
    bk = [[None] * 4 for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n):
        for c in range(4):
            v = dp[i][c]
            if v == INF:
                continue
            nv = v + SKIP
            if nv < dp[i + 1][c]:
                dp[i + 1][c] = nv
                bk[i + 1][c] = (c, False)
            nv = v + _fit(tokens[i], order[c], pcs)
            nc = (c + 1) % 4
            if nv < dp[i + 1][nc]:
                dp[i + 1][nc] = nv
                bk[i + 1][nc] = (c, True)
    if dp[n][0] == INF:
        return []
    assign = []
    i, c = n, 0
    while i > 0:
        pc, used = bk[i][c]
        assign.append((i - 1, pc if used else None))
        i, c = i - 1, pc
    assign.reverse()
    rows = []
    cur = {}
    for idx, col in assign:
        if col is None:
            continue
        cur[order[col]] = tokens[idx]
        if col == 3:
            rows.append([cur.get(k, '') for k in COLS])
            cur = {}
    return rows


# ---------------------------------------------------------------- candidate lattice

def _solve_row(row, style, deadline):
    ctok, qtok, utok, atok = row
    code = best_code(ctok)
    Q = {0: qty_cands(qtok, 0)}
    U = {0: money_cands(utok, style, 0)}
    A = {0: money_cands(atok, style, 0)}
    found = {}

    def add(q, u, a, cost):
        key = (q, u)
        if key not in found or cost < found[key][0]:
            found[key] = (cost, q, u, a)

    for q, (cq, _) in Q[0].items():
        for u, (cu, _) in U[0].items():
            a = q * u
            if a in A[0]:
                add(q, u, a, cq + cu + A[0][a][0])
    for lv in (1, 2):
        if found and min(v[0] for v in found.values()) < float(lv) - 1e-9:
            break
        if lv == 2 and time.perf_counter() > deadline:
            break
        Q[lv] = qty_cands(qtok, lv)
        U[lv] = money_cands(utok, style, lv)
        A[lv] = money_cands(atok, style, lv)
        Qs, Us, As = Q[1], U[1], A[1]
        Qf, Uf, Af = Q[lv], U[lv], A[lv]
        for q, (cq, _) in Qs.items():
            for u, (cu, _) in Us.items():
                a = q * u
                e = Af.get(a)
                if e is not None:
                    add(q, u, a, cq + cu + e[0])
        for q, (cq, _) in Qs.items():
            for a, (ca, _) in As.items():
                if a % q == 0:
                    u = a // q
                    e = Uf.get(u)
                    if e is not None:
                        add(q, u, a, cq + ca + e[0])
        for u, (cu, _) in Us.items():
            for a, (ca, _) in As.items():
                if a % u == 0:
                    q = a // u
                    e = Qf.get(q)
                    if e is not None:
                        add(q, u, a, cu + ca + e[0])
        if lv == 2:
            for q, (cq, _) in Qf.items():
                for u, (cu, _) in U[0].items():
                    a = q * u
                    e = Af.get(a)
                    if e is not None:
                        add(q, u, a, cq + cu + e[0])
                for a, (ca, _) in A[0].items():
                    if a % q == 0:
                        e = Uf.get(a // q)
                        if e is not None:
                            add(q, a // q, a, cq + ca + e[0])
    alts = sorted(found.values(), key=lambda t: (t[0], t[1], t[2]))
    if alts:
        best = alts[0]
        alts = [list(x) for x in alts if x[0] <= best[0] + 2.5][:12]
        return {'code': code, 'alts': alts, 'ok': True}
    qd = Q.get(1) or Q[0]
    ud = U.get(1) or U[0]
    ad = A.get(1) or A[0]
    q = min(qd, key=lambda k: (qd[k][0], k)) if qd else 1
    u = min(ud, key=lambda k: (ud[k][0], k)) if ud else 0
    a = min(ad, key=lambda k: (ad[k][0], k)) if ad else q * u
    if A[0] and Q[0]:
        a0 = min(A[0])
        q0 = min(Q[0])
        if a0 % q0 == 0:
            q, u, a = q0, a0 // q0, a0
    return {'code': code, 'alts': [[9.0, q, u, a]], 'ok': False}


def node_lattice(state, params):
    t0 = time.perf_counter()
    lay = state['layout']
    style = lay['style']
    out_secs = []
    for sec in lay['sections']:
        rows = []
        for r in sec['rows']:
            elapsed = time.perf_counter() - t0
            if elapsed > 0.85:
                q = qty_cands(r[1], 0)
                u = money_cands(r[2], style, 0)
                rows.append({'code': best_code(r[0]),
                             'alts': [[9.0, min(q) if q else 1, min(u) if u else 0, 0]],
                             'ok': False})
                continue
            rows.append(_solve_row(r, style, t0 + 0.6))
        sub = None
        if sec['subtotal']:
            sc = money_cands(sec['subtotal'], style, 0)
            if len(sc) == 1:
                sub = list(sc.keys())[0]
        out_secs.append({'rows': rows, 'subtotal': sub})
    state['solved'] = out_secs
    return state


def node_reconcile(state, params):
    items = []
    for sec in state.get('solved', []):
        rows = sec['rows']
        choice = [0] * len(rows)
        sub = sec['subtotal']
        if sub is not None and rows:
            s = sum(r['alts'][0][3] for r in rows)
            if s != sub:
                best = None
                for i, r in enumerate(rows):
                    b = r['alts'][0]
                    for j in range(1, len(r['alts'])):
                        alt = r['alts'][j]
                        if s - b[3] + alt[3] == sub:
                            d = alt[0] - b[0]
                            if best is None or d < best[0]:
                                best = (d, i, j)
                if best is not None:
                    choice[best[1]] = best[2]
        for i, r in enumerate(rows):
            a = r['alts'][choice[i]]
            items.append({'code': r['code'], 'qty': int(a[1]), 'unit_cents': int(a[2])})
    state['output'] = {'items': items}
    return state

import re
import time

NAMES = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
LET2DIG = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'i': '1', 'S': '5', 's': '5',
           'B': '8', 'Z': '2', 'z': '2', 'G': '6'}
DIG2LET = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
# shown digit -> possible true digits (inverse of the misread table)
SHOWN2TRUE = {'0': '68', '1': '47', '2': '7', '3': '589', '4': '19', '5': '6',
              '6': '05', '7': '12', '8': '03', '9': '34'}
DIGITS = '0123456789'
SUB_C = 1.0
DUP_C = 1.0
INS_C = 1.5


# ---------------------------------------------------------------- layout parsing

def _classify_sep(b):
    if '|' in b:
        return '|'
    if ';' in b:
        return ';'
    if '\t' in b:
        return '\t'
    return 'sp'


def _split_line(l, sep):
    if sep == '|':
        parts = l.split('|')
    elif sep == ';':
        parts = l.split(';')
    elif sep == '\t':
        parts = l.split('\t')
    else:
        parts = re.split(r' {2,}|\t', l)
    return [p.strip() for p in parts if p.strip()]


def _trails(l, sep):
    if sep == '|':
        return l.rstrip().endswith('|')
    if sep == ';':
        return l.rstrip().endswith(';')
    if sep == '\t':
        return l.rstrip(' ').endswith('\t')
    return l.endswith('  ')


def parse_layout(state, params):
    inp = state.get('input') or {}
    text = inp.get('text', '') if isinstance(inp, dict) else str(inp)
    text = str(text or '')
    lines = text.replace('\r\n', '\n').replace('\r', '\n').split('\n')
    order = list(NAMES)
    sep = None
    ci = -1
    for k, l in enumerate(lines):
        if re.match(r'^\s*COLUMNS\b', l):
            ci = k
            body = l.split(':', 1)[1] if ':' in l else l
            pos = []
            ok = True
            for n in NAMES:
                m = re.search(r'\b' + n + r'\b', body)
                if m is None:
                    ok = False
                    pos.append((10 ** 6, n))
                else:
                    pos.append((m.start(), n))
            pos.sort()
            if ok:
                order = [n for _, n in pos]
                between = body[pos[0][0] + len(pos[0][1]):pos[1][0]]
                sep = _classify_sep(between)
            break
    if sep is None:
        cnt = {'|': text.count(' | '), ';': text.count(';'), '\t': text.count('\t'),
               'sp': text.count('   ')}
        best = 'sp'
        bv = -1
        for key in ['|', ';', '\t', 'sp']:
            if cnt[key] > bv:
                bv = cnt[key]
                best = key
        sep = best
    secs = []
    pre = []
    cur = None
    start = ci + 1 if ci >= 0 else 0
    for l in lines[start:]:
        st = l.strip()
        if not st:
            continue
        if st.startswith('MANIFEST') and ci < 0:
            continue
        if re.match(r'^=+\s*SECTION\b', st) or (st.startswith('==') and 'SECTION' in st):
            cur = {'lines': [], 'sub': None}
            secs.append(cur)
            continue
        m = re.match(r'^SUBTOTAL\b\s*(.*)$', st)
        if m:
            if cur is not None:
                cur['sub'] = m.group(1).strip()
            elif not secs and pre:
                secs.append({'lines': pre, 'sub': m.group(1).strip()})
                pre = []
            cur = None
            continue
        if re.match(r'^TOTAL\b', st):
            break
        entry = {'toks': _split_line(l, sep), 'trail': _trails(l, sep)}
        if cur is None:
            if not secs:
                pre.append(entry)
            continue
        cur['lines'].append(entry)
    if not secs and pre:
        secs.append({'lines': pre, 'sub': None})
    pcs_count = 0
    for s in secs:
        for ln in s['lines']:
            for t in ln['toks']:
                if re.search(r'pcs\s*$', t, re.I):
                    pcs_count += 1
    state['layout'] = {'order': order, 'sep': sep, 'sections': secs, 'pcs': pcs_count >= 1}
    return state


# ---------------------------------------------------------------- value candidates

def _edits(s):
    res = [(s, 0.0)]
    n = len(s)
    for k in range(n):
        ch = s[k]
        for t in SHOWN2TRUE.get(ch, ''):
            res.append((s[:k] + t + s[k + 1:], SUB_C))
        if k > 0 and s[k - 1] == ch:
            res.append((s[:k] + s[k + 1:], DUP_C))
    for k in range(n + 1):
        for d in DIGITS:
            res.append((s[:k] + d + s[k:], INS_C))
    return res


def _check_digit(L, D4):
    p = ord(L[0]) - 64 + ord(L[1]) - 64
    return (int(D4[0]) + 2 * int(D4[1]) + 3 * int(D4[2]) + 4 * int(D4[3]) + p) % 10


def code_fallback(tok):
    s = re.sub(r'\s', '', tok or '')
    L = ''.join(DIG2LET.get(c, c) for c in s[:2]).upper()
    L = ''.join(c if 'A' <= c <= 'Z' else 'A' for c in L)
    L = (L + 'AA')[:2]
    D = ''.join(LET2DIG.get(c, c) for c in s[2:])
    D = ''.join(c for c in D if c in DIGITS)
    D = (D + '0000')[:4]
    return L + D + str(_check_digit(L, D))


def code_cands(tok):
    s = re.sub(r'\s', '', tok)
    if len(s) < 6 or len(s) > 8:
        return None
    L = ''.join(DIG2LET.get(c, c) for c in s[:2])
    if not re.fullmatch(r'[A-Z]{2}', L):
        return None
    dl = []
    for c in s[2:]:
        if c in DIGITS:
            dl.append(c)
        elif c in LET2DIG:
            dl.append(LET2DIG[c])
        else:
            return None
    D = ''.join(dl)
    best = None
    for E, c in _edits(D):
        if len(E) != 5:
            continue
        if _check_digit(L, E[:4]) == int(E[4]):
            key = (c, E)
            if best is None or key < best:
                best = key
    if best is None:
        return (code_fallback(tok), 4.0)
    return (L + best[1], best[0])


def money_cands(tok):
    if tok is None:
        return None
    s = tok.replace("'", '').replace(' ', '').replace('\u2019', '')
    if not s:
        return None
    t = []
    for c in s:
        if c in DIGITS or c in '.,':
            t.append(c)
        elif c in LET2DIG:
            t.append(LET2DIG[c])
        else:
            return None
    s = ''.join(t)
    marks = [k for k, c in enumerate(s) if c in '.,']
    if len(marks) > 1:
        return None
    if not re.search(r'[0-9]', s):
        return None
    out = {}

    def add(ip, fp, c):
        if not ip or len(fp) != 2:
            return
        if len(ip) > 1 and ip[0] == '0':
            return
        v = int(ip) * 100 + int(fp)
        if v <= 0:
            return
        if c < out.get(v, 99.0):
            out[v] = c

    if marks:
        m = marks[0]
        I = s[:m]
        F = s[m + 1:]
        if len(I) > 9 or len(F) > 4:
            return None
        for I2, c in _edits(I):
            add(I2, F, c)
        for F2, c in _edits(F):
            if c > 0:
                add(I, F2, c)
    else:
        if len(s) > 11:
            return None
        for D, c in _edits(s):
            if len(D) >= 3:
                add(D[:-2], D[-2:], c + 0.3)
    return out or None


def qty_cands(tok):
    s = tok.strip()
    pcs = False
    m = re.match(r'^(.*?)\s*pcs$', s, re.I)
    if m:
        s = m.group(1)
        pcs = True
    s = s.replace(' ', '')
    if not s or len(s) > 4:
        return None
    t = []
    for c in s:
        if c in DIGITS:
            t.append(c)
        elif c in LET2DIG:
            t.append(LET2DIG[c])
        else:
            return None
    s = ''.join(t)
    out = {}
    for D, c in _edits(s):
        if not D or (len(D) > 1 and D[0] == '0'):
            continue
        v = int(D)
        if 1 <= v <= 500 and c < out.get(v, 99.0):
            out[v] = c
    if not out:
        return None
    return (out, pcs)


def consist(qc, uc, ac, full):
    res = {}
    qi = list(qc.items())
    ui = list(uc.items())
    ai = list(ac.items())
    ulow = [x for x in ui if x[1] < 0.9]
    alow = [x for x in ai if x[1] < 0.9]
    qlow = [x for x in qi if x[1] < 0.9]

    def put(q, u, a, c):
        k = (q, u, a)
        if c < res.get(k, 1e9):
            res[k] = c

    for q, cq in qi:
        for u, cu in ulow:
            a = q * u
            ca = ac.get(a)
            if ca is not None:
                put(q, u, a, cq + cu + 0.9 * ca)
        for a, ca in alow:
            if a % q == 0:
                u = a // q
                cu = uc.get(u)
                if cu is not None:
                    put(q, u, a, cq + cu + 0.9 * ca)
    for q, cq in qlow:
        for u, cu in ui:
            a = q * u
            ca = ac.get(a)
            if ca is not None:
                put(q, u, a, cq + cu + 0.9 * ca)
    if full:
        for q, cq in qi:
            for u, cu in ui:
                a = q * u
                ca = ac.get(a)
                if ca is not None:
                    put(q, u, a, cq + cu + 0.9 * ca)
    return sorted((c, q, u, a) for (q, u, a), c in res.items())


def _argmin(d):
    if not d:
        return None
    best = None
    for v, c in d.items():
        key = (c, v)
        if best is None or key < best:
            best = key
    return best[1]


# ---------------------------------------------------------------- decoding

def _decode(lay):
    t0 = time.perf_counter()
    order = lay.get('order') or list(NAMES)
    if sorted(order) != sorted(NAMES):
        order = list(NAMES)
    pos = {n: order.index(n) for n in NAMES}
    secs = lay.get('sections') or []
    pcs_doc = bool(lay.get('pcs'))
    tokcache = {}

    def tc(kind, t):
        key = kind + '\x00' + t
        if key in tokcache:
            return tokcache[key]
        if kind == 'C':
            r = code_cands(t)
        elif kind == 'Q':
            r = qty_cands(t)
        else:
            r = money_cands(t)
        tokcache[key] = r
        return r

    def skip_cost(toks):
        fits = 0
        for t in toks:
            if tc('C', t) is not None or tc('Q', t) is not None or tc('M', t) is not None:
                fits += 1
        if fits == 0:
            return 0.5
        return 2.5 + 1.5 * fits

    rowcache = {}

    def row_eval(toks):
        if toks in rowcache:
            return rowcache[toks]
        cost = 0.0
        cc = tc('C', toks[pos['CODE']])
        if cc is None:
            cost += 12.0
        else:
            cost += cc[1]
        qr = tc('Q', toks[pos['QTY']])
        qc = None
        if qr is None:
            cost += 10.0
        else:
            qc = qr[0]
            if qr[1] != pcs_doc:
                cost += 3.0
        uc = tc('M', toks[pos['UNIT']])
        ac = tc('M', toks[pos['AMOUNT']])
        if uc is None:
            cost += 10.0
        if ac is None:
            cost += 10.0
        if qc and uc and ac:
            cb = consist(qc, uc, ac, False)
            if cb:
                cost += cb[0][0]
            else:
                cost += 6.0 + min(qc.values()) + min(uc.values()) + min(ac.values())
        sc = 10.0 - cost
        rowcache[toks] = sc
        return sc

    def row_detail(toks, full):
        cc = tc('C', toks[pos['CODE']])
        code = cc[0] if cc is not None else code_fallback(toks[pos['CODE']])
        qr = tc('Q', toks[pos['QTY']])
        qc = qr[0] if qr is not None else None
        uc = tc('M', toks[pos['UNIT']])
        ac = tc('M', toks[pos['AMOUNT']])
        alts = []
        if qc and uc and ac:
            alts = consist(qc, uc, ac, full)[:40]
        qb = _argmin(qc)
        ub = _argmin(uc)
        ab = _argmin(ac)
        if qb is None:
            if ab and ub and ab % ub == 0 and 1 <= ab // ub <= 500:
                qb = ab // ub
            else:
                qb = 1
        if ub is None:
            ub = (ab // qb) if ab else 0
        return {'code': code, 'qc': qc, 'uc': uc, 'alts': alts, 'ch': 0, 'q': qb, 'u': ub}

    def dp_section(sec):
        toks = []
        lidx = []
        lranges = []
        for ln in sec.get('lines') or []:
            tl = ln.get('toks') or []
            if not tl:
                continue
            s = len(toks)
            for t in tl:
                toks.append(t)
                lidx.append(len(lranges))
            lranges.append((s, len(toks), bool(ln.get('trail'))))
        T = len(toks)
        if T == 0:
            return []
        lstart = [False] * T
        for s, e, _ in lranges:
            lstart[s] = True
        skipc = [skip_cost(toks[s:e]) for s, e, _ in lranges]

        def gen(i):
            out = []

            def rec(idxs, k, extra, nsk):
                if len(idxs) == 4:
                    last = idxs[-1]
                    s, e, tr = lranges[lidx[last]]
                    pen = 1.0 if (last == e - 1 and tr) else 0.0
                    out.append((tuple(idxs), extra + pen, k))
                    return
                if k >= T:
                    return
                if lstart[k]:
                    lp = lidx[idxs[-1]]
                    pen = 0.0 if lranges[lp][2] else 0.6
                    rec(idxs + [k], k + 1, extra + pen, nsk)
                    if nsk < 2:
                        L = lidx[k]
                        rec(idxs, lranges[L][1], extra + skipc[L], nsk + 1)
                else:
                    rec(idxs + [k], k + 1, extra, nsk)

            rec([i], i + 1, 0.0, 0)
            return out

        NEG = -1e18
        dp = [NEG] * (T + 1)
        bp = [None] * (T + 1)
        dp[0] = 0.0

        def relax(j, v, info):
            if v > dp[j] + 1e-9:
                dp[j] = v
                bp[j] = info

        for i in range(T):
            if dp[i] <= NEG / 2:
                continue
            base = dp[i]
            if lstart[i]:
                L = lidx[i]
                relax(lranges[L][1], base - skipc[L], (i, None))
            relax(i + 1, base - 7.0, (i, None))
            for idxs, extra, nxt in gen(i):
                rt = tuple(toks[k] for k in idxs)
                sc = row_eval(rt) - extra
                relax(nxt, base + sc, (i, rt))
        rows = []
        j = T
        guard = 0
        while j > 0 and bp[j] is not None and guard < 100000:
            guard += 1
            i, rt = bp[j]
            if rt is not None:
                rows.append(rt)
            j = i
        rows.reverse()
        return rows

    def reconcile(dets, S):
        if not S or not dets:
            return

        def cur_a(d):
            if d['alts']:
                return d['alts'][d['ch']][3]
            return d['q'] * d['u']

        sum0 = sum(cur_a(d) for d in dets)
        best = (S.get(sum0, 1e9), None)
        for r, d in enumerate(dets):
            a0 = cur_a(d)
            if d['alts']:
                c0 = d['alts'][0][0]
                for k in range(1, len(d['alts'])):
                    c, q, u, a = d['alts'][k]
                    cs = S.get(sum0 - a0 + a)
                    if cs is not None:
                        tot = c - c0 + cs
                        if tot < best[0]:
                            best = (tot, (r, 'alt', k, 0))
            else:
                qc = d['qc']
                uc = d['uc']
                if qc and uc:
                    for s, cs in S.items():
                        if cs > 1.6:
                            continue
                        need = s - (sum0 - a0)
                        if need <= 0:
                            continue
                        for q, cq in qc.items():
                            if need % q == 0:
                                cu = uc.get(need // q)
                                if cu is not None:
                                    tot = cq + cu + cs + 0.5
                                    if tot < best[0]:
                                        best = (tot, (r, 'set', q, need // q))
        if best[1] is None or best[0] > 6.0:
            return
        r, kind, x, y = best[1]
        if kind == 'alt':
            dets[r]['ch'] = x
        else:
            dets[r]['q'] = x
            dets[r]['u'] = y

    items = []
    for sec in secs:
        rows = dp_section(sec)
        full = (time.perf_counter() - t0) < 0.6
        dets = [row_detail(rt, full) for rt in rows]
        try:
            if (time.perf_counter() - t0) < 0.75:
                reconcile(dets, money_cands(sec.get('sub')))
        except Exception:
            pass
        for d in dets:
            if d['alts']:
                c, q, u, a = d['alts'][d['ch']]
            else:
                q, u = d['q'], d['u']
            items.append({'code': str(d['code']), 'qty': int(q), 'unit_cents': int(u)})
    return items


def viterbi_decode(state, params):
    try:
        items = _decode(state.get('layout') or {})
    except Exception:
        items = []
    state['output'] = {'items': items}
    return state

import re
import time

INV = {'0': '68', '1': '74', '2': '7', '3': '589', '4': '19', '5': '6',
       '6': '05', '7': '12', '8': '03', '9': '34'}
L2D = {'O': '0', 'o': '0', 'Q': '0', 'D': '0', 'l': '1', 'I': '1', 'i': '1', '|': '1',
       'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6', 'b': '6'}
D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
SUBC = {'0': 1.1, '1': 1.1, '2': 1.0, '3': 1.1, '4': 1.1, '5': 1.1, '6': 1.1, '7': 1.1, '8': 1.1, '9': 1.1}
COLNAMES = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
FREE = 4.0
REWARD = 12.0


def _check(L, D):
    return (int(D[0]) + 2 * int(D[1]) + 3 * int(D[2]) + 4 * int(D[3])
            + ord(L[0]) - 64 + ord(L[1]) - 64) % 10 == int(D[4])


def code_cands(tok):
    t = re.sub(r'\s+', '', tok)
    if len(t) < 6 or len(t) > 9:
        return {}
    L = ''.join(D2L.get(c, c) for c in t[:2]).upper()
    if not re.match(r'^[A-Z]{2}$', L):
        return {}
    D = ''.join(L2D.get(c, c) for c in t[2:])
    if not D.isdigit() or len(D) < 4 or len(D) > 6:
        return {}
    res = {}
    if len(D) == 5:
        if _check(L, D):
            return {L + D: 0.0}
        for i in range(5):
            for a in INV[D[i]]:
                d2 = D[:i] + a + D[i + 1:]
                if _check(L, d2):
                    res[L + d2] = SUBC[a]
        if not res:
            fixed = D[:4] + str((int(D[0]) + 2 * int(D[1]) + 3 * int(D[2]) + 4 * int(D[3])
                                 + ord(L[0]) + ord(L[1]) - 128) % 10)
            res[L + fixed] = 3.0
    elif len(D) == 4:
        for i in range(5):
            for a in '0123456789':
                d2 = D[:i] + a + D[i:]
                if _check(L, d2):
                    res.setdefault(L + d2, 1.0)
    else:
        for i in range(6):
            d2 = D[:i] + D[i + 1:]
            if _check(L, d2):
                c = 1.0 if ((i > 0 and D[i - 1] == D[i]) or (i < 5 and D[i + 1] == D[i])) else 2.0
                if res.get(L + d2, 9) > c:
                    res[L + d2] = c
        if not res:
            res[L + D[:5]] = 3.0
    return res


def qty_cands(tok):
    t = re.sub(r'(?i)p\s*c\s*s', '', tok)
    t = re.sub(r'\s+', '', t)
    t = ''.join(L2D.get(c, c) for c in t)
    if not t.isdigit():
        return {}
    res = {}

    def add(s, c):
        if not s or (len(s) > 1 and s[0] == '0'):
            return
        v = int(s)
        if 1 <= v <= 500 and res.get(v, 99) > c:
            res[v] = c
    add(t, 0.0)
    for i in range(len(t)):
        for a in INV[t[i]]:
            add(t[:i] + a + t[i + 1:], SUBC[a])
        if i + 1 < len(t) and t[i] == t[i + 1]:
            add(t[:i] + t[i + 1:], 1.0)
        add(t[:i] + t[i + 1:], 2.0)
    for i in range(len(t) + 1):
        for a in '0123456789':
            add(t[:i] + a + t[i:], 1.2)
    return res


def money_cands(tok, mark, grp):
    t = re.sub(r'\s+', '', tok)
    t = ''.join(L2D.get(c, c) for c in t)
    t = re.sub(r"[`\u2019]", "'", t)
    if not re.match(r"^[0-9'.,]+$", t) or not re.search(r'\d', t):
        return {}
    other = ',' if mark == '.' else '.'
    t = t.replace(other, mark) if mark not in t else t.replace(other, '')
    res = {}

    def add(i, f, c):
        if len(f) != 2 or not i:
            return
        if len(i) > 1 and i[0] == '0':
            return
        v = int(i) * 100 + int(f)
        if res.get(v, 99) > c:
            res[v] = c

    if mark in t:
        k = t.rfind(mark)
        iraw = t[:k].replace(mark, '')
        frac = t[k + 1:].replace("'", '')
        groups = iraw.split("'")
        ip = iraw.replace("'", '')
        if len(frac) == 2:
            add(ip, frac, 0.0)
            s = ip + frac
            n = len(ip)
            for j in range(len(s)):
                for a in INV[s[j]]:
                    s2 = s[:j] + a + s[j + 1:]
                    add(s2[:n], s2[n:], SUBC[a])
            ins_pos = list(range(len(ip) + 1))
            del_pos = list(range(len(ip)))
            if grp and len(groups) > 1:
                later = groups[1:]
                off = len(groups[0])
                bad_ins = None
                bad_del = None
                pos = off
                for g in later:
                    if len(g) == 2 and bad_ins is None:
                        bad_ins = (pos, pos + 2)
                    if len(g) == 4 and bad_del is None:
                        bad_del = (pos, pos + 4)
                    pos += len(g)
                if bad_ins:
                    ins_pos = list(range(bad_ins[0], bad_ins[1] + 1))
                else:
                    ins_pos = list(range(0, off + 1)) if off < 3 else []
                if bad_del:
                    del_pos = list(range(bad_del[0], bad_del[1]))
                else:
                    del_pos = list(range(0, off))
            elif grp:
                if len(ip) >= 3:
                    ins_pos = []
            for j in ins_pos:
                for a in '0123456789':
                    add(ip[:j] + a + ip[j:], frac, 1.2)
            for j in del_pos:
                c = 1.0 if ((j > 0 and ip[j - 1] == ip[j]) or (j + 1 < len(ip) and ip[j + 1] == ip[j])) else 2.0
                add(ip[:j] + ip[j + 1:], frac, c)
        elif len(frac) == 1:
            for j in range(2):
                for a in '0123456789':
                    add(ip, frac[:j] + a + frac[j:], 1.2)
        elif len(frac) == 3:
            for j in range(3):
                c = 1.0 if ((j > 0 and frac[j - 1] == frac[j]) or (j < 2 and frac[j + 1] == frac[j])) else 2.0
                add(ip, frac[:j] + frac[j + 1:], c)
    else:
        d = t.replace("'", '')
        if len(d) >= 3:
            add(d[:-2], d[-2:], 1.0)
        elif len(d) == 2:
            add('0', d, 1.5)
    return res


def solve_row(Q, U, A):
    """min-cost (q, u, a) with q*u == a; a field may be 'free' at cost FREE."""
    best = [1e9, None]
    Ql = sorted(Q.items(), key=lambda x: x[1])
    Ul = sorted(U.items(), key=lambda x: x[1])
    Al = sorted(A.items(), key=lambda x: x[1])
    minU = Ul[0][1] if Ul else 0
    for q, cq in Ql:
        if cq + minU >= best[0]:
            break
        for u, cu in Ul:
            c = cq + cu
            if c >= best[0]:
                break
            a = q * u
            ca = A.get(a)
            if ca is not None:
                if c + ca < best[0]:
                    best = [c + ca, (q, u, a)]
            elif c + FREE < best[0]:
                best = [c + FREE, (q, u, a)]
    if Ql and Al and FREE + Ql[0][1] + Al[0][1] < best[0]:
        for q, cq in Ql:
            if FREE + cq + Al[0][1] >= best[0]:
                break
            for a, ca in Al:
                c = FREE + cq + ca
                if c >= best[0]:
                    break
                if a % q == 0 and a > 0:
                    best = [c, (q, a // q, a)]
    if Ul and Al and FREE + Ul[0][1] + Al[0][1] < best[0]:
        for u, cu in Ul:
            if FREE + cu + Al[0][1] >= best[0]:
                break
            if u <= 0:
                continue
            for a, ca in Al:
                c = FREE + cu + ca
                if c >= best[0]:
                    break
                if a % u == 0 and 1 <= a // u <= 500:
                    best = [c, (a // u, u, a)]
    if best[1] is None:
        q = Ql[0][0] if Ql else 1
        u = Ul[0][0] if Ul else (Al[0][0] // q if Al else 0)
        best = [2 * FREE + 1, (q, u, q * u)]
    return best


def subtotal_repair(rows, S, cands):
    """If the row amounts disagree with the section subtotal, re-solve one row
    against the amount the subtotal implies (cheapest extra cost)."""
    if not S:
        return
    total = sum(r["_a"] for r in rows)
    if S.get(total, 99) <= 1.2:
        return
    best = None
    for idx, r in enumerate(rows):
        Q = cands(r["_t"][0], 'QTY')
        U = cands(r["_t"][1], 'UNIT')
        A = cands(r["_t"][2], 'AMOUNT')
        for sv, cs in S.items():
            if cs > 1.2:
                continue
            tgt = sv - (total - r["_a"])
            if tgt <= 0:
                continue
            ca = A.get(tgt, FREE)
            sub = solve_row(Q, U, {tgt: ca})
            if sub[1] is None or sub[1][2] != tgt:
                continue
            extra = sub[0] - r["_c"] + cs
            if best is None or extra < best[0]:
                best = (extra, idx, sub[1])
    if best is not None and best[0] < 3.5:
        q, u, a = best[2]
        r = rows[best[1]]
        r["qty"], r["unit_cents"], r["_a"] = int(q), int(u), int(a)


def _detect_sep(colline, body):
    m = re.search(r'COLUMNS:?\s?(.*)$', colline)
    rest = m.group(1) if m else colline
    pos = sorted((rest.find(n), n) for n in COLNAMES if rest.find(n) >= 0)
    if len(pos) >= 2:
        a = pos[0][0] + len(pos[0][1])
        between = rest[a:pos[1][0]]
        if '|' in between:
            return '|'
        if ';' in between:
            return ';'
        if '\t' in between:
            return '\t'
        if len(between) >= 2 and between.strip() == '':
            return '   '
    cnt = {'|': 0, ';': 0, '\t': 0, '   ': 0}
    for ln in body:
        for k in cnt:
            cnt[k] += ln.count(k)
    return max(cnt, key=lambda k: cnt[k])


def _split(line, sep):
    if sep == '|':
        parts = re.split(r'\s*\|\s*', line)
    elif sep == ';':
        parts = re.split(r'\s*;\s*', line)
    elif sep == '\t':
        parts = [p.strip() for p in line.split('\t')]
    else:
        parts = [p.strip() for p in re.split(r' {3,}', line)]
    while parts and parts[0].strip() == '':
        parts.pop(0)
    while parts and parts[-1].strip() == '':
        parts.pop()
    return parts


def parse_structure(state, params):
    text = state["input"].get("text", "") if isinstance(state.get("input"), dict) else ""
    if not isinstance(text, str):
        text = ""
    lines = text.replace('\r', '').split('\n')
    ci = -1
    for i, ln in enumerate(lines):
        if 'COLUMNS' in ln:
            ci = i
            break
    colline = lines[ci] if ci >= 0 else ''
    pos = []
    for n in COLNAMES:
        p = colline.find(n)
        pos.append((p if p >= 0 else 999 + len(pos), n))
    order = [n for _, n in sorted(pos)]
    body = lines[ci + 1:] if ci >= 0 else lines
    sep = _detect_sep(colline, body)
    sections = []
    cur = None
    for li, ln in enumerate(body):
        s = ln.strip()
        if not s:
            continue
        if re.match(r'^=+\s*SECTION', s):
            cur = {"tokens": []}
            sections.append(cur)
            continue
        if s.startswith('SUBTOTAL') or s.startswith('TOTAL') or s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            if s.startswith('TOTAL'):
                cur = None
            elif s.startswith('SUBTOTAL'):
                if cur is not None:
                    cur["subtotal"] = s[len('SUBTOTAL'):].strip()
                cur = None
            continue
        if cur is None:
            cur = {"tokens": []}
            sections.append(cur)
        parts = _split(ln, sep)
        for k, p in enumerate(parts):
            cur["tokens"].append([p, li, k == 0, k == len(parts) - 1])
    dots = commas = apos = 0
    for sec in sections:
        for tk in sec["tokens"]:
            t = tk[0]
            if re.search(r'[.]\w\w$', t):
                dots += 1
            if re.search(r'[,]\w\w$', t):
                commas += 1
            if re.search(r"\d'\w\w\w", t):
                apos += 1
    state["parsed"] = {"order": order, "sep": sep, "sections": sections,
                       "mark": ',' if commas > dots else '.', "grp": apos > 0}
    return state


def viterbi_decode(state, params):
    P = state["parsed"]
    order = P["order"]
    mark = P["mark"]
    grp = P["grp"]
    ci = {n: i for i, n in enumerate(order)}
    cache = {}

    def cands(text, col):
        key = (text, col)
        r = cache.get(key)
        if r is None:
            if col == 'CODE':
                r = code_cands(text)
            elif col == 'QTY':
                r = qty_cands(text)
            else:
                r = money_cands(text, mark, grp)
            cache[key] = r
        return r

    def junk_pen(text):
        if re.search(r'[A-Za-z]{3,}|-{2,}|={2,}', text):
            return 0.1
        return 0.5

    items = []
    for sec in P["sections"]:
        toks = sec["tokens"]
        T = len(toks)
        if T == 0:
            continue
        rowcache = {}

        def row_score(win):
            r = rowcache.get(win)
            if r is not None:
                return r
            texts = [toks[j][0] for j in win]
            C = cands(texts[ci['CODE']], 'CODE')
            if not C:
                rowcache[win] = (None, None)
                return rowcache[win]
            code, cc = min(C.items(), key=lambda x: x[1])
            Q = cands(texts[ci['QTY']], 'QTY')
            U = cands(texts[ci['UNIT']], 'UNIT')
            A = cands(texts[ci['AMOUNT']], 'AMOUNT')
            cost, (q, u, a) = solve_row(Q, U, A)
            lay = 0.0
            if not toks[win[0]][2]:
                lay += 0.6
            for k in range(1, 4):
                if toks[win[k]][1] != toks[win[k - 1]][1]:
                    lay += 0.3
            res = (cc + cost + lay, {"code": code, "qty": int(q), "unit_cents": int(u),
                                     "_a": int(a), "_c": cost,
                                     "_t": [texts[ci['QTY']], texts[ci['UNIT']], texts[ci['AMOUNT']]]})
            rowcache[win] = res
            return res

        INF = 1e18
        dp = [INF] * (T + 1)
        bp = [None] * (T + 1)
        dp[0] = 0.0
        jp = [junk_pen(t[0]) for t in toks]
        for i in range(T):
            if dp[i] >= INF:
                continue
            v = dp[i] + jp[i]
            if v < dp[i + 1]:
                dp[i + 1] = v
                bp[i + 1] = (i, None)
            wins = [((i, i + 1, i + 2, i + 3), 0.0)]
            for s in range(1, 4):
                if i + s < T:
                    idx = [i + k for k in range(5) if k != s]
                    wins.append((tuple(idx), jp[i + s] + 0.8))
            for win, extra in wins:
                if win[-1] >= T:
                    continue
                sc, item = row_score(win)
                if item is None:
                    continue
                v = dp[i] + sc + extra - REWARD
                e = win[-1] + 1
                if v < dp[e]:
                    dp[e] = v
                    bp[e] = (i, item)
        out = []
        j = T
        while j > 0 and bp[j] is not None:
            i, item = bp[j]
            if item is not None:
                out.append(dict(item))
            j = i
        out.reverse()
        if sec.get("subtotal") and out:
            subtotal_repair(out, money_cands(sec["subtotal"], mark, grp), cands)
        items.extend(out)
    clean = [{"code": it["code"], "qty": it["qty"], "unit_cents": it["unit_cents"]} for it in items]
    state["output"] = {"items": clean}
    return state


def finalize(state, params):
    out = state.get("output")
    if not isinstance(out, dict) or not isinstance(out.get("items"), list):
        state["output"] = {"items": []}
    state.pop("parsed", None)
    return state

import re
import time

LOOK_L2D = {'O': '0', 'o': '0', 'D': '0', 'Q': '0', 'l': '1', 'I': '1', 'i': '1',
            'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6', 'b': '6'}
LOOK_D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
MIS_FWD = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
           '6': '50', '7': '12', '8': '30', '9': '43'}
MIS_REV = {}
for _t, _obs in MIS_FWD.items():
    for _o in _obs:
        MIS_REV.setdefault(_o, []).append(_t)

C_MIS = 1.0
C_DEL = 1.0
C_DEL_ND = 2.2
C_INS = 1.1
C_LOOK = 0.05
C_NOMARK = 0.4
W_FIELD = 3.2
W_SUB = 3.0
W_TOT = 3.0
ROW_K = 8
BEAM_CAP = 600
SEC_M = 6


def detect_sep(text):
    for ln in text.split('\n'):
        if ln.strip().startswith('COLUMNS'):
            rest = ln.split(':', 1)[1] if ':' in ln else ln.strip()[7:]
            if '|' in rest:
                return 'pipe', rest
            if ';' in rest:
                return 'semi', rest
            if '\t' in rest:
                return 'tab', rest
            return 'space', rest
    return None, ''


def split_line(line, sep):
    if sep == 'pipe':
        parts = line.split('|')
    elif sep == 'semi':
        parts = line.split(';')
    elif sep == 'tab':
        parts = line.split('\t')
    else:
        parts = re.split(r' {2,}|\t', line)
    parts = [p.strip() for p in parts]
    if parts and parts[-1] == '':
        parts = parts[:-1]
    if parts and parts[0] == '':
        parts = parts[1:]
    return parts


TOK_RE = re.compile(r"^[A-Za-z0-9.,']*( ?[pP][cC][sS])?$")


def is_data_line(parts, sep):
    if not parts:
        return False
    for p in parts:
        if len(p) > 16 or not TOK_RE.match(p):
            return False
    return any(re.search(r'[0-9A-Za-z]', p) for p in parts)


def parse_layout(state, params):
    text = (state.get('input') or {}).get('text', '') or ''
    sep, colrest = detect_sep(text)
    if sep is None:
        sep = 'semi'
        for s, ch in (('pipe', ' | '), ('semi', ';'), ('tab', '\t')):
            if ch in text:
                sep = s
                break
    cols = re.findall(r'CODE|QTY|UNIT|AMOUNT', colrest)
    if sorted(cols) != ['AMOUNT', 'CODE', 'QTY', 'UNIT']:
        cols = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    sections = []
    cur = None
    total_tok = None
    items_tok = None
    for raw in text.split('\n'):
        ln = raw.rstrip('\r')
        st = ln.strip()
        if not st:
            continue
        if st.startswith('MANIFEST') or st.startswith('COLUMNS'):
            continue
        if st.startswith('==') and 'SECTION' in st:
            cur = {'tokens': [], 'sub': None}
            sections.append(cur)
            continue
        if st.startswith('SUBTOTAL'):
            if cur is None:
                cur = {'tokens': [], 'sub': None}
                sections.append(cur)
            cur['sub'] = st[len('SUBTOTAL'):].strip()
            continue
        if st.startswith('TOTAL'):
            m = re.match(r'TOTAL\s+(.*?)\s+ITEMS\s*(.*)$', st)
            if m:
                total_tok, items_tok = m.group(1).strip(), m.group(2).strip()
            else:
                total_tok = st[5:].strip()
            continue
        parts = split_line(ln, sep)
        if not is_data_line(parts, sep):
            continue
        if cur is None:
            cur = {'tokens': [], 'sub': None}
            sections.append(cur)
        cur['tokens'].extend(parts)
    state['layout'] = {'cols': cols, 'sections': sections, 'total': total_tok, 'items': items_tok}
    return state


def type_cost(tok, col):
    t = (tok or '').strip()
    if col == 'CODE':
        if re.match(r'^[A-Z0-9]{2}[0-9A-Za-z]{4,6}$', t):
            return 0.0 if re.match(r'^[A-Z]', t) or len(t) >= 6 else 0.5
        return 1.5
    if col == 'QTY':
        if re.search(r'pcs', t, re.I):
            return 0.0
        if re.match(r'^[0-9OlISBZG]{0,4}$', t):
            return 0.0
        return 1.5
    if re.match(r'^[A-Z]{2}', t):
        return 1.5
    if re.search(r'[.,]', t) or len(t) >= 3:
        return 0.0
    return 0.8


def align_rows(tokens, cols, n_hint):
    n = len(tokens)
    if n % 4 == 0 and all(type_cost(tokens[i], cols[i % 4]) < 1.0 for i in range(n)):
        return [tokens[i:i + 4] for i in range(0, n, 4)]
    INF = 1e18
    dp = [[INF] * 4 for _ in range(n + 1)]
    bp = [[None] * 4 for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        for c in range(4):
            v = dp[i][c]
            if v >= INF:
                continue
            nc = (c + 1) % 4
            if v + 4.0 < dp[i][nc]:
                dp[i][nc] = v + 4.0
                bp[i][nc] = (i, c, 'g')
        if i == n:
            break
        for c in range(4):
            v = dp[i][c]
            if v >= INF:
                continue
            nc = (c + 1) % 4
            w = v + type_cost(tokens[i], cols[c])
            if w < dp[i + 1][nc]:
                dp[i + 1][nc] = w
                bp[i + 1][nc] = (i, c, 'm')
            w = v + 4.0
            if w < dp[i + 1][c]:
                dp[i + 1][c] = w
                bp[i + 1][c] = (i, c, 's')
    best_c, best_v = 0, dp[n][0]
    for c in range(1, 4):
        v = dp[n][c] + 4.0 * (4 - c)
        if v < best_v:
            best_v, best_c = v, c
    ops = []
    i, c = n, best_c
    guard = 0
    while not (i == 0 and c == 0) and guard < 10 * (n + 4):
        guard += 1
        b = bp[i][c]
        if b is None:
            break
        ops.append(b)
        i, c = b[0], b[1]
    ops.reverse()
    rows = []
    cur = [None, None, None, None]
    for pi, pc, op in ops:
        if op == 's':
            continue
        cur[pc] = tokens[pi] if op == 'm' else None
        if pc == 3:
            rows.append(cur)
            cur = [None, None, None, None]
    if any(x is not None for x in cur):
        rows.append(cur)
    return rows


def clean_digits(t):
    out = []
    look = 0
    for ch in t:
        if ch.isdigit():
            out.append(ch)
        elif ch in LOOK_L2D:
            out.append(LOOK_L2D[ch])
            look += 1
    return ''.join(out), look


def digit_edits(D, allow_ins, allow_del, two_mis=True, ins_range=None, del_range=None):
    res = {D: 0.0}

    def put(s, c):
        if c < res.get(s, 1e9):
            res[s] = c
    L = len(D)
    mis_pos = []
    for i, ch in enumerate(D):
        for t in MIS_REV.get(ch, ()):
            put(D[:i] + t + D[i + 1:], C_MIS)
            mis_pos.append((i, t))
    if two_mis:
        for a in range(len(mis_pos)):
            i, t = mis_pos[a]
            for b in range(a + 1, len(mis_pos)):
                j, u = mis_pos[b]
                if j <= i:
                    continue
                put(D[:i] + t + D[i + 1:j] + u + D[j + 1:], 2 * C_MIS)
    if allow_del:
        lo, hi = del_range if del_range else (0, L)
        for i in range(max(lo, 0), min(hi, L)):
            dup = (i > 0 and D[i] == D[i - 1]) or (i + 1 < L and D[i] == D[i + 1])
            put(D[:i] + D[i + 1:], C_DEL if dup else C_DEL_ND)
    if allow_ins:
        lo, hi = ins_range if ins_range else (0, L + 1)
        for i in range(max(lo, 0), min(hi, L + 1)):
            for d in '0123456789':
                put(D[:i] + d + D[i:], C_INS)
    return res


def _add_misreads(cand):
    extra = {}
    for s, c in cand.items():
        for i, ch in enumerate(s):
            for tt in MIS_REV.get(ch, ()):
                s2 = s[:i] + tt + s[i + 1:]
                if c + C_MIS < extra.get(s2, 99):
                    extra[s2] = c + C_MIS
    for s, c in extra.items():
        if c < cand.get(s, 99):
            cand[s] = c
    return cand


def money_cands(tok):
    if tok is None:
        return {}
    t = tok.strip().replace(' ', '')
    D, look = clean_digits(t)
    base = look * C_LOOK
    mpos = max(t.rfind('.'), t.rfind(','))
    if mpos >= 0:
        dec = len(clean_digits(t[mpos + 1:])[0])
    else:
        dec = None
        base += C_NOMARK
    L = len(D)
    if dec == 2:
        cand = digit_edits(D, True, True, True, ins_range=(0, L - 1), del_range=(0, L - 2))
    elif dec == 1:
        cand = {}
        for i in range(max(L - 1, 0), L + 1):
            for d in '0123456789':
                s = D[:i] + d + D[i:]
                cand[s] = min(cand.get(s, 99), C_INS)
        cand = _add_misreads(cand)
    elif dec == 3:
        cand = {}
        for i in range(max(L - 3, 0), L):
            c = C_DEL if (i > 0 and D[i] == D[i - 1]) or (i + 1 < L and D[i] == D[i + 1]) else C_DEL_ND
            s = D[:i] + D[i + 1:]
            cand[s] = min(cand.get(s, 99), c)
        cand = _add_misreads(cand)
    else:
        cand = digit_edits(D, True, True, True)
    out = {}
    for s, c in cand.items():
        if len(s) < 3:
            continue
        ip = s[:-2]
        if len(ip) > 1 and ip[0] == '0':
            continue
        v = int(s)
        if v <= 0:
            continue
        cc = c + base
        if cc < out.get(v, 1e9):
            out[v] = cc
    return out


def qty_cands(tok):
    if tok is None:
        return {}
    t = re.sub(r'[pP][cC][sS]', '', tok).strip().replace(' ', '')
    D, look = clean_digits(t)
    base = look * C_LOOK
    cand = digit_edits(D, True, True, True)
    out = {}
    for s, c in cand.items():
        if not s or (len(s) > 1 and s[0] == '0'):
            continue
        v = int(s)
        if 1 <= v <= 500:
            cc = c + base
            if cc < out.get(v, 1e9):
                out[v] = cc
    return out


def int_cands(tok):
    if tok is None:
        return {}
    D, look = clean_digits(tok.strip())
    out = {}
    for s, c in digit_edits(D, True, True, True).items():
        if s and not (len(s) > 1 and s[0] == '0'):
            v = int(s)
            if c + look * C_LOOK < out.get(v, 1e9):
                out[v] = c + look * C_LOOK
    return out


def best_code(tok):
    if tok is None:
        return 'AA00000'
    t = re.sub(r'\s', '', tok)
    variants = []
    L = len(t)
    if L == 7:
        variants.append((t, 0.0))
    if L == 6:
        for i in range(2, 7):
            variants.append((t[:i] + '?' + t[i:], C_INS))
    if L == 8:
        for i in range(2, 8):
            dup = t[i] == t[i - 1] or (i + 1 < L and t[i] == t[i + 1])
            variants.append((t[:i] + t[i + 1:], C_DEL if dup else C_DEL_ND))
    if L == 5:
        for i in range(2, 6):
            for j in range(i, 7):
                s = t[:i] + '?' + t[i:]
                s = s[:j] + '?' + s[j:]
                if len(s) == 7:
                    variants.append((s, 2 * C_INS))
    if L == 9:
        for i in range(2, 9):
            s = t[:i] + t[i + 1:]
            for j in range(2, 8):
                variants.append((s[:j] + s[j + 1:], 2 * C_DEL))
    if not variants:
        variants.append(((t + '???????')[:7], 3.0))
    best = None
    for v, vc in variants:
        lc = 0.0
        letters = []
        for ch in v[:2]:
            if 'A' <= ch <= 'Z':
                letters.append(ch)
            elif ch in LOOK_D2L:
                letters.append(LOOK_D2L[ch])
                lc += C_LOOK
            elif ch.isalpha() and ch.upper() >= 'A' and ch.upper() <= 'Z':
                letters.append(ch.upper())
                lc += 0.5
            else:
                letters.append(None)
                lc += 1.0
        opts = []
        for ch in v[2:7]:
            if ch == '?':
                opts.append([(d, 0.0) for d in range(10)])
            elif ch.isdigit():
                opts.append([(int(ch), 0.0)] + [(int(x), C_MIS) for x in MIS_REV.get(ch, ())])
            elif ch in LOOK_L2D:
                opts.append([(int(LOOK_L2D[ch]), C_LOOK)])
            else:
                opts.append([(d, 2.0) for d in range(10)])
        lopts = []
        for x in letters:
            if x is None:
                lopts.append([chr(65 + k) for k in range(26)])
            else:
                lopts.append([x])
        base = vc + lc
        for l1 in lopts[0]:
            for l2 in lopts[1]:
                p1 = ord(l1) - 64
                p2 = ord(l2) - 64

                def rec(k, acc, cost):
                    nonlocal best
                    if best is not None and base + cost >= best[0]:
                        return
                    if k == 4:
                        need = (acc[0] + 2 * acc[1] + 3 * acc[2] + 4 * acc[3] + p1 + p2) % 10
                        for d, c in opts[4]:
                            if d == need:
                                tot = base + cost + c
                                if best is None or tot < best[0]:
                                    best = (tot, l1 + l2 + ''.join(str(x) for x in acc) + str(d))
                        return
                    for d, c in opts[k]:
                        rec(k + 1, acc + [d], cost + c)
                rec(0, [], 0.0)
    if best is None:
        v = variants[0][0]
        s1 = ''.join(LOOK_D2L.get(ch, ch) for ch in v[:2]).upper()
        s2 = ''.join(ch if ch.isdigit() else LOOK_L2D.get(ch, '0') for ch in v[2:7])
        s1 = re.sub(r'[^A-Z]', 'A', s1)
        s2 = re.sub(r'[^0-9]', '0', s2)
        return (s1 + 'AA')[:2] + (s2 + '00000')[:5]
    return best[1]


def row_cands(qtok, utok, atok, K):
    Q = qty_cands(qtok)
    U = money_cands(utok)
    A = money_cands(atok)
    res = {}

    def put(q, u, a, c):
        key = (q, u)
        if c < res.get(key, (1e9, 0))[0]:
            res[key] = (c, a)
    if Q and U and A:
        Ql = sorted(Q.items(), key=lambda x: x[1])
        Ul = sorted(U.items(), key=lambda x: x[1])
        for q, cq in Ql:
            if cq > 3.3:
                break
            for u, cu in Ul:
                if cq + cu > 3.3:
                    break
                a = q * u
                ca = A.get(a)
                if ca is not None:
                    put(q, u, a, cq + cu + ca)
    Qc = [(q, c) for q, c in Q.items() if c <= 1.05]
    Uc = [(u, c) for u, c in U.items() if c <= 1.05]
    Ac = [(a, c) for a, c in A.items() if c <= 1.05]
    for q, cq in Qc:
        for u, cu in Uc:
            put(q, u, q * u, cq + cu + W_FIELD)
    for q, cq in Qc:
        for a, ca in Ac:
            if a % q == 0:
                put(q, a // q, a, cq + ca + W_FIELD)
    for u, cu in Uc:
        for a, ca in Ac:
            if a % u == 0:
                q = a // u
                if 1 <= q <= 500:
                    put(q, u, a, cu + ca + W_FIELD)
    if not res:
        q = min(Q.items(), key=lambda x: x[1])[0] if Q else 1
        if U:
            u = min(U.items(), key=lambda x: x[1])[0]
        elif A:
            u = max(1, min(A.items(), key=lambda x: x[1])[0] // q)
        else:
            u = 100
        put(q, u, q * u, 2 * W_FIELD)
    lst = sorted(((c, q, u, a) for (q, u), (c, a) in res.items()), key=lambda x: (x[0], x[1], x[2]))
    return lst[:K]


def section_beam(rcands, sub_c, deadline):
    layers = []
    beam = {0: (0.0, None, -1)}
    for cl in rcands:
        nb = {}
        for s, (c, _, _) in beam.items():
            for k, (rc, q, u, a) in enumerate(cl):
                ns = s + a
                nc = c + rc
                old = nb.get(ns)
                if old is None or nc < old[0]:
                    nb[ns] = (nc, s, k)
        late = time.perf_counter() > deadline
        if len(nb) > BEAM_CAP or late:
            cap = 20 if late else BEAM_CAP
            nb = dict(sorted(nb.items(), key=lambda x: (x[1][0], x[0]))[:cap])
        layers.append(nb)
        beam = nb
    final = []
    for s, (c, _, _) in beam.items():
        sc = min(sub_c.get(s, W_SUB), W_SUB) if sub_c is not None else 0.0
        final.append((c + sc, s))
    final.sort()
    out = []
    for c, s in final[:SEC_M]:
        choices = []
        cur = s
        for r in range(len(layers) - 1, -1, -1):
            _, prev, k = layers[r][cur]
            choices.append(k)
            cur = prev
        choices.reverse()
        out.append((c, s, choices))
    return out


def solve(state, params):
    t0 = time.perf_counter()
    deadline = t0 + 0.6
    lay = state.get('layout') or {}
    cols = lay.get('cols') or ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    ci = {c: i for i, c in enumerate(cols)}
    items_c = int_cands(lay.get('items'))
    n_hint = min(items_c.items(), key=lambda x: x[1])[0] if items_c else None
    sections = lay.get('sections') or []
    sec_rows = []
    for sec in sections:
        rows = align_rows(sec['tokens'], cols, n_hint) if sec.get('tokens') else []
        sec_rows.append(rows)
    sec_opts = []
    sec_rc = []
    for si, sec in enumerate(sections):
        rows = sec_rows[si]
        rc = []
        for row in rows:
            K = ROW_K if time.perf_counter() < deadline else 2
            rc.append(row_cands(row[ci['QTY']], row[ci['UNIT']], row[ci['AMOUNT']], K))
        sec_rc.append(rc)
        sub_c = money_cands(sec['sub']) if sec.get('sub') else None
        if not rows:
            sec_opts.append([(0.0, 0, [])])
            continue
        opts = section_beam(rc, sub_c, deadline)
        if not opts:
            opts = [(0.0, 0, [0] * len(rows))]
        sec_opts.append(opts)
    tot_c = money_cands(lay.get('total')) if lay.get('total') else None
    dp = {0: (0.0, [])}
    for opts in sec_opts:
        nd = {}
        for s, (c, ch) in dp.items():
            for j, (oc, os_, _) in enumerate(opts):
                ns = s + os_
                nc = c + oc
                if ns not in nd or nc < nd[ns][0]:
                    nd[ns] = (nc, ch + [j])
        if len(nd) > 3000:
            nd = dict(sorted(nd.items(), key=lambda x: (x[1][0], x[0]))[:3000])
        dp = nd
    best = None
    for s, (c, ch) in dp.items():
        tc = min(tot_c.get(s, W_TOT), W_TOT) if tot_c is not None else 0.0
        v = c + tc
        if best is None or v < best[0]:
            best = (v, ch)
    pick = best[1] if best else [0] * len(sec_opts)
    items = []
    for si, rows in enumerate(sec_rows):
        choices = sec_opts[si][pick[si]][2] if si < len(pick) else []
        for r, row in enumerate(rows):
            k = choices[r] if r < len(choices) else 0
            cl = sec_rc[si][r]
            if cl:
                k = min(k, len(cl) - 1)
                _, q, u, _ = cl[k]
            else:
                q, u = 1, 0
            items.append({'code': best_code(row[ci['CODE']]), 'qty': int(q), 'unit_cents': int(u)})
    state['output'] = {'items': items}
    return state

import re
import time

DIG = '0123456789'
DIGSET = set(DIG)
LOOK_DIG = {'O': '0', 'o': '0', 'l': '1', 'I': '1', 'S': '5', 'B': '8', 'Z': '2', 'G': '6'}
LOOK_LET = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G', 'l': 'I'}
MIS_SHOWN = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
             '6': '50', '7': '12', '8': '30', '9': '43'}
NUMCH = set('0123456789OolISBZG')

C_MIS = 2.0
C_DUP = 2.5
C_LOST = 2.5
C_MARK = 1.5
C_SUB = 5.0
C_INS = 6.0
P_FREE = 9.0
SKIP = -5.0


def _src():
    s = {}
    for t, shown in MIS_SHOWN.items():
        for o in shown:
            s[o] = s.get(o, '') + t
    return s


SRC = _src()


# ---------------------------------------------------------------- layout node
def _sc_code(t):
    if not re.fullmatch(r"[A-Za-z0-9]{6,8}", t):
        return -4.0
    a, b = t[0], t[1]
    lets = sum(1 for c in (a, b) if c.isalpha() or c in '012568')
    if lets < 2:
        return -3.0
    if not all(c in NUMCH for c in t[2:]):
        return -2.0
    if a.isalpha() or b.isalpha():
        return 0.0
    return -1.0


def _sc_qty(t):
    m = re.fullmatch(r"([A-Za-z0-9]*)\s*(pcs)?", t)
    if not m:
        return -4.0
    d = m.group(1)
    if not d:
        return -1.0 if m.group(2) else -4.0
    if not all(c in NUMCH for c in d):
        return -3.0
    if len(d) <= 3:
        return 0.0
    if len(d) == 4:
        return -1.0
    return -3.0


def _sc_money(t):
    if 'pcs' in t:
        return -4.0
    u = t.replace("'", "")
    if not u:
        return -4.0
    marks = sum(1 for c in u if c in '.,')
    body = [c for c in u if c not in '.,']
    if not all(c in NUMCH for c in body):
        return -3.0
    if marks == 1:
        return 0.0 if body else -3.0
    if marks == 0:
        return -1.5 if len(body) >= 3 else -3.0
    return -3.0


def _segment(tokens, order):
    fns = {'CODE': _sc_code, 'QTY': _sc_qty, 'UNIT': _sc_money, 'AMOUNT': _sc_money}
    n = len(tokens)
    rowsc = [None] * n
    for i in range(n - 3):
        rowsc[i] = sum(fns[order[k]](tokens[i + k]) for k in range(4))
    dp = [dict() for _ in range(n + 1)]
    dp[0][0] = (0.0, None)

    def upd(d, r, s, bp):
        o = d.get(r)
        if o is None or s > o[0] + 1e-9:
            d[r] = (s, bp)

    for i in range(n):
        if not dp[i]:
            continue
        best = max(v[0] for v in dp[i].values())
        for r, (s, _) in list(dp[i].items()):
            if s < best - 20:
                continue
            upd(dp[i + 1], r, s + SKIP, (i, r, 0))
            if rowsc[i] is not None:
                upd(dp[i + 4], r + 1, s + rowsc[i], (i, r, 1))
    return dp


def _backtrack(dp, tokens, n, r):
    rows = []
    i, rr = n, r
    while i > 0:
        ent = dp[i].get(rr)
        if ent is None or ent[1] is None:
            break
        pi, pr, kind = ent[1]
        if kind == 1:
            rows.append(tokens[pi:pi + 4])
        i, rr = pi, pr
    rows.reverse()
    return rows


def parse_layout(state, params):
    inp = state.get('input') or {}
    text = inp.get('text', '') if isinstance(inp, dict) else str(inp)
    if not isinstance(text, str):
        text = str(text)
    lines = text.replace('\r', '').split('\n')
    order = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    splitre = r"\s*\|\s*"
    for ln in lines:
        st = ln.strip()
        if st.startswith('COLUMNS'):
            body = st.split(':', 1)[1] if ':' in st else st[7:]
            pos = [(body.find(nm), nm) for nm in order]
            if all(p >= 0 for p, _ in pos):
                order = [nm for _, nm in sorted(pos)]
            if '|' in body:
                splitre = r"\s*\|\s*"
            elif ';' in body:
                splitre = r"\s*;\s*"
            elif '\t' in body:
                splitre = r"\t+"
            else:
                splitre = r" {2,}"
            break
    sections = []
    cur = None
    total = None
    items = None
    tokre = re.compile(r"[A-Za-z0-9.,']*( ?pcs)?")
    for ln in lines:
        st = ln.strip()
        if not st:
            continue
        if st.startswith('MANIFEST') or st.startswith('COLUMNS'):
            continue
        if re.match(r"^==\s*SECTION", st):
            cur = {'tokens': [], 'sub': None}
            sections.append(cur)
            continue
        if st.startswith('SUBTOTAL'):
            parts = st[8:].split()
            if cur is None:
                cur = {'tokens': [], 'sub': None}
                sections.append(cur)
            if parts:
                cur['sub'] = parts[0]
            continue
        if st.startswith('TOTAL'):
            m = re.match(r"TOTAL\s+(\S*)\s*ITEMS\s*(\S*)", st)
            if m:
                total = m.group(1) or None
                items = m.group(2) or None
            else:
                parts = st[5:].split()
                total = parts[0] if parts else None
            continue
        toks = [t.strip() for t in re.split(splitre, ln.strip('\n'))]
        toks = [t for t in toks if t]
        if not toks:
            continue
        if not all(tokre.fullmatch(t) for t in toks):
            continue
        if cur is None:
            cur = {'tokens': [], 'sub': None}
            sections.append(cur)
        cur['tokens'].extend(toks)

    # segmentation, with ITEMS deciding the row count
    seg = []
    for sec in sections:
        toks = sec['tokens']
        dp = _segment(toks, order)
        fin = dp[len(toks)]
        if not fin:
            fin = {0: (SKIP * len(toks), None)}
        best = max(v[0] for v in fin.values())
        opts = {r: v[0] for r, v in fin.items() if v[0] >= best - 15}
        seg.append((dp, toks, opts))
    combos = {0: (0.0, [])}
    for dp, toks, opts in seg:
        nc = {}
        for tot, (s, ch) in combos.items():
            for r, sc in opts.items():
                k = tot + r
                v = s + sc
                if k not in nc or v > nc[k][0]:
                    nc[k] = (v, ch + [r])
        combos = nc
    items_obs = None
    if items:
        items_obs = ''.join(LOOK_DIG.get(c, c) for c in items)
    bestk = None
    for k, (s, ch) in combos.items():
        sc = s
        if items_obs:
            sc -= min(_dist(str(k), items_obs), P_FREE)
        if bestk is None or sc > bestk[0]:
            bestk = (sc, ch)
    out_secs = []
    for idx, (dp, toks, opts) in enumerate(seg):
        r = bestk[1][idx] if bestk else 0
        rows = _backtrack(dp, toks, len(toks), r) if r else []
        recs = []
        for rw in rows:
            d = {}
            for k in range(4):
                d[order[k]] = rw[k]
            recs.append(d)
        out_secs.append({'rows': recs, 'sub': sections[idx]['sub']})
    state['layout'] = {'sections': out_secs, 'total': total, 'items': items}
    return state


# ---------------------------------------------------------------- channel model
def _ins_cost(O, k):
    if k > 0 and O[k] == O[k - 1] and O[k] != '.':
        return C_DUP
    return C_INS


def _dist(T, O):
    """Cost of the true rendering T being shown as observed O."""
    m = len(O)
    insc = [_ins_cost(O, j) for j in range(m)]
    prev = [0.0] * (m + 1)
    for j in range(1, m + 1):
        prev[j] = prev[j - 1] + insc[j - 1]
    for t in T:
        dc = C_MARK if t == '.' else C_LOST
        ms = MIS_SHOWN.get(t, '')
        cur = [prev[0] + dc] + [0.0] * m
        for j in range(1, m + 1):
            o = O[j - 1]
            if t == o:
                sc = 0.0
            elif t == '.' or o == '.':
                sc = 9.0
            elif o in ms:
                sc = C_MIS
            else:
                sc = C_SUB
            v = prev[j - 1] + sc
            v2 = prev[j] + dc
            if v2 < v:
                v = v2
            v3 = cur[j - 1] + insc[j - 1]
            if v3 < v:
                v = v3
            cur[j] = v
        prev = cur
    return prev[m]


def _inv1(s):
    out = {}

    def add(x, c):
        o = out.get(x)
        if o is None or c < o:
            out[x] = c
    nd = s.count('.')
    for i, ch in enumerate(s):
        if ch in DIGSET:
            for t in SRC.get(ch, ''):
                add(s[:i] + t + s[i + 1:], C_MIS)
            if i > 0 and s[i - 1] == ch:
                add(s[:i] + s[i + 1:], C_DUP)
        elif ch == '.':
            if nd > 1:
                add(s[:i] + s[i + 1:], C_INS)
        else:
            for d in DIG:
                add(s[:i] + d + s[i + 1:], C_SUB)
            add(s[:i] + s[i + 1:], C_INS)
    for i in range(len(s) + 1):
        for d in DIG:
            add(s[:i] + d + s[i:], C_LOST)
    return out


def _alldig(x):
    return bool(x) and all(c in DIGSET for c in x)


def _parse_money(x):
    nd = x.count('.')
    if nd == 1:
        a, b = x.split('.')
        extra = 0.0
    elif nd == 0:
        if len(x) < 3:
            return None
        a, b = x[:-2], x[-2:]
        extra = C_MARK
    else:
        return None
    if len(b) != 2 or not _alldig(a) or not _alldig(b):
        return None
    if len(a) > 1 and a[0] == '0':
        return None
    v = int(a) * 100 + int(b)
    if v <= 0:
        return None
    return v, extra


def _parse_qty(x):
    if not _alldig(x) or x[0] == '0' or len(x) > 3:
        return None
    v = int(x)
    if 1 <= v <= 500:
        return v
    return None


def _norm_num(t):
    t = t.replace("'", '').replace(' ', '').replace('\t', '')
    out = []
    for c in t:
        if c in ',.':
            out.append('.')
        else:
            out.append(LOOK_DIG.get(c, c))
    return ''.join(out)


def _norm_qty(t):
    t = t.strip()
    if t.endswith('pcs'):
        t = t[:-3]
    return _norm_num(t)


def _fmt(c):
    return '%d.%02d' % (c // 100, c % 100)


def _money_cands(s):
    res = {}
    base = None
    pv = _parse_money(s)
    if pv:
        res[pv[0]] = pv[1]
        base = (pv[0], pv[1])
    for x, c in _inv1(s).items():
        pv = _parse_money(x)
        if pv:
            cc = c + pv[1]
            o = res.get(pv[0])
            if o is None or cc < o:
                res[pv[0]] = cc
    return res, base


def _qty_cands(s):
    res = {}
    base = None
    v = _parse_qty(s)
    if v:
        res[v] = 0.0
        base = (v, 0.0)
    for x, c in _inv1(s).items():
        v = _parse_qty(x)
        if v:
            o = res.get(v)
            if o is None or c < o:
                res[v] = c
    return res, base


def _row_cands(row, K):
    qo = _norm_qty(row.get('QTY', ''))
    uo = _norm_num(row.get('UNIT', ''))
    ao = _norm_num(row.get('AMOUNT', ''))
    Q, qb = _qty_cands(qo)
    U, ub = _money_cands(uo)
    A, ab = _money_cands(ao)
    MAXC = 14.0
    tr = {}

    def add(q, u, c):
        if c > MAXC:
            return
        k = (q, u)
        o = tr.get(k)
        if o is None or c < o:
            tr[k] = c
    Ul = list(U.items())
    for q, cq in Q.items():
        for u, cu in Ul:
            c = cq + cu
            if c > 5.0:
                continue
            ca = A.get(q * u)
            if ca is not None:
                add(q, u, c + ca)
    if ub:
        u0, cu0 = ub
        for q, cq in Q.items():
            add(q, u0, cq + cu0 + _dist(_fmt(q * u0), ao))
    if qb:
        q0, cq0 = qb
        for u, cu in Ul:
            if cu <= 2.5:
                add(q0, u, cq0 + cu + _dist(_fmt(q0 * u), ao))
    if ab:
        a0, ca0 = ab
        for q, cq in Q.items():
            if a0 % q == 0:
                u = a0 // q
                add(q, u, cq + ca0 + _dist(_fmt(u), uo))
        for u, cu in Ul:
            if a0 % u == 0:
                q = a0 // u
                if 1 <= q <= 500:
                    add(q, u, cu + ca0 + _dist(str(q), qo))
    lst = sorted(((c, q, u) for (q, u), c in tr.items()), key=lambda x: (x[0], x[1], x[2]))
    if not lst:
        q = min(Q.items(), key=lambda x: (x[1], x[0]))[0] if Q else 1
        if U:
            u = min(U.items(), key=lambda x: (x[1], x[0]))[0]
        elif A:
            a = min(A.items(), key=lambda x: (x[1], x[0]))[0]
            u = max(1, a // q)
        else:
            u = 100
        lst = [(30.0, q, u)]
    return lst[:K]


# ---------------------------------------------------------------- codes
def _check_ok(L, d):
    if len(d) != 5 or not _alldig(d):
        return False
    p = (ord(L[0]) - 64) + (ord(L[1]) - 64)
    s = int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p
    return s % 10 == int(d[4])


def _repair_code(tok):
    t = re.sub(r"\s", "", tok)
    if len(t) < 2:
        t = (t + 'AA')[:2] + t[2:]
    L = ''
    for c in t[:2]:
        c2 = LOOK_LET.get(c, c).upper()
        if not ('A' <= c2 <= 'Z'):
            c2 = 'A'
        L += c2
    D = ''.join(LOOK_DIG.get(c, c) for c in t[2:])
    if _check_ok(L, D):
        return L + D
    best = None
    frontier = {D: 0.0}
    seen = {D: 0.0}
    for depth in (1, 2):
        nf = {}
        for s, c in frontier.items():
            for x, cc in _inv1(s).items():
                if abs(len(x) - 5) > 2 - depth:
                    continue
                v = c + cc
                if x in seen and seen[x] <= v:
                    continue
                seen[x] = v
                nf[x] = v
        for x, v in nf.items():
            if _check_ok(L, x):
                if best is None or v < best[0] or (v == best[0] and x < best[1]):
                    best = (v, x)
        if best is not None:
            break
        frontier = nf
    if best is not None:
        return L + best[1]
    dd = ''.join(c for c in D if c in DIGSET)
    dd = (dd + '0000')[:4]
    p = (ord(L[0]) - 64) + (ord(L[1]) - 64)
    s = int(dd[0]) + 2 * int(dd[1]) + 3 * int(dd[2]) + 4 * int(dd[3]) + p
    return L + dd + str(s % 10)


# ---------------------------------------------------------------- beam node
def _section_beam(rowcands, sub_obs, M, BEAM, MARGIN):
    layers = []
    states = {0: (0.0, None, -1)}
    for cands in rowcands:
        new = {}
        for s, st in states.items():
            c0 = st[0]
            for k, (cc, q, u) in enumerate(cands):
                ns = s + q * u
                nc = c0 + cc
                o = new.get(ns)
                if o is None or nc < o[0]:
                    new[ns] = (nc, s, k)
        best = min(v[0] for v in new.values())
        items = [(v[0], s) for s, v in new.items() if v[0] <= best + MARGIN]
        if len(items) > BEAM:
            items.sort()
            items = items[:BEAM]
        states = {s: new[s] for _, s in items}
        layers.append(states)
    sub_d = None
    if sub_obs is not None:
        sub_d, _ = _money_cands(sub_obs)
    fin = []
    for s, st in states.items():
        if sub_obs is None:
            sc = 0.0
        else:
            sc = sub_d.get(s)
            if sc is None:
                sc = min(_dist(_fmt(s), sub_obs), P_FREE)
            else:
                sc = min(sc, P_FREE)
        fin.append((st[0] + sc, s))
    fin.sort()
    out = []
    for tot, s in fin[:M]:
        ch = []
        cs = s
        for li in range(len(layers) - 1, -1, -1):
            st = layers[li][cs]
            ch.append(st[2])
            cs = st[1]
        ch.reverse()
        out.append((tot, s, ch))
    return out


def solve(state, params):
    t0 = time.perf_counter()
    lay = state.get('layout') or {'sections': [], 'total': None, 'items': None}
    secs = lay.get('sections') or []
    results = []
    codes_all = []
    cands_all = []
    for sec in secs:
        rows = sec.get('rows') or []
        codes_all.append([_repair_code(r.get('CODE', '')) for r in rows])
        late = time.perf_counter() - t0 > 0.6
        rc = [_row_cands(r, 1 if late else 10) for r in rows]
        cands_all.append(rc)
    for si, sec in enumerate(secs):
        rc = cands_all[si]
        sub = sec.get('sub')
        sub_obs = _norm_num(sub) if sub else None
        if time.perf_counter() - t0 > 0.8:
            ch = [0] * len(rc)
            s = sum(c[0][1] * c[0][2] for c in rc)
            results.append([(sum(c[0][0] for c in rc), s, ch)])
        else:
            results.append(_section_beam(rc, sub_obs, 12, 250, 12.0))
    # reconcile sections with TOTAL
    glob = {0: (0.0, [])}
    for res in results:
        ng = {}
        for s, (c, ch) in glob.items():
            for k, (sc, ss, _) in enumerate(res):
                key = s + ss
                v = c + sc
                o = ng.get(key)
                if o is None or v < o[0]:
                    ng[key] = (v, ch + [k])
        if len(ng) > 300:
            keep = sorted(ng.items(), key=lambda x: x[1][0])[:300]
            ng = dict(keep)
        glob = ng
    tot = lay.get('total')
    tot_obs = _norm_num(tot) if tot else None
    best = None
    for s, (c, ch) in glob.items():
        v = c
        if tot_obs is not None:
            v += min(_dist(_fmt(s), tot_obs), P_FREE)
        if best is None or v < best[0]:
            best = (v, ch)
    items = []
    for si, res in enumerate(results):
        k = best[1][si] if best else 0
        ch = res[k][2]
        for ri, ci in enumerate(ch):
            c = cands_all[si][ri][ci]
            items.append({'code': codes_all[si][ri], 'qty': int(c[1]), 'unit_cents': int(c[2])})
    state['output'] = {'items': items}
    return state

import re
import time


def _tables():
    conf = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63',
            '6': '50', '7': '12', '8': '30', '9': '43'}
    rev = {}
    for o, outs in conf.items():
        for x in outs:
            rev.setdefault(x, [])
            if o not in rev[x]:
                rev[x].append(o)
    for d in '0123456789':
        rev.setdefault(d, [])
    l2d = {'O': '0', 'o': '0', 'D': '0', 'Q': '0', 'l': '1', 'I': '1', 'i': '1', '|': '1',
           'S': '5', 's': '5', 'B': '8', 'Z': '2', 'z': '2', 'G': '6', 'b': '6'}
    d2l = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G'}
    return conf, rev, l2d, d2l


def _check_ok(letters, digs):
    if len(digs) != 5 or len(letters) != 2:
        return False
    d = [ord(c) - 48 for c in digs]
    p1 = ord(letters[0]) - 64
    p2 = ord(letters[1]) - 64
    return (d[0] + 2 * d[1] + 3 * d[2] + 4 * d[3] + p1 + p2) % 10 == d[4]


def _digit_edits(s, rev):
    out = []
    n = len(s)
    for i in range(n):
        ch = s[i]
        if ch.isdigit():
            for c in rev[ch]:
                out.append(s[:i] + c + s[i + 1:])
    for i in range(n + 1):
        for d in '0123456789':
            out.append(s[:i] + d + s[i:])
    for i in range(n - 1):
        if s[i] == s[i + 1] and s[i].isdigit():
            out.append(s[:i] + s[i + 1:])
    return out


def _align_cost(C, O, conf):
    n, m = len(C), len(O)
    INF = 99.0
    dp = [[INF] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        row = dp[i]
        for j in range(m + 1):
            v = row[j]
            if v >= INF:
                continue
            if i < n:
                c = C[i]
                cd = c.isdigit()
                if j < m:
                    o = O[j]
                    if c == o:
                        w = 0.0
                    elif cd and o.isdigit():
                        w = 1.0 if o in conf[c] else 2.5
                    elif (not cd) and (not o.isdigit()):
                        w = 1.5
                    else:
                        w = 3.0
                    if v + w < dp[i + 1][j + 1]:
                        dp[i + 1][j + 1] = v + w
                    if cd and j + 1 < m and O[j] == c and O[j + 1] == c:
                        if v + 1.0 < dp[i + 1][j + 2]:
                            dp[i + 1][j + 2] = v + 1.0
                w = 1.0 if (cd or c in '.,') else 2.0
                if v + w < dp[i + 1][j]:
                    dp[i + 1][j] = v + w
            if j < m:
                if v + 2.5 < row[j + 1]:
                    row[j + 1] = v + 2.5
    return dp[n][m]


def solve(state, params):
    t0 = time.process_time()
    conf, rev, l2d, d2l = _tables()
    text = state.get("input", {}).get("text", "") or ""
    lines = text.split("\n")

    names = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    order = names[:]
    sep = ';'
    for ln in lines:
        s = ln.strip('\r')
        if s.lstrip().startswith('COLUMNS'):
            rest = s.split(':', 1)[1] if ':' in s else s[7:]
            pos = []
            for nm in names:
                k = rest.find(nm)
                if k < 0:
                    pos = []
                    break
                pos.append((k, nm))
            if pos:
                pos.sort()
                order = [nm for _, nm in pos]
                sep = rest[pos[0][0] + len(pos[0][1]):pos[1][0]]
            break
    if '|' in sep:
        splitre = re.compile(r'\s*\|\s*')
    elif ';' in sep:
        splitre = re.compile(r'\s*;\s*')
    elif '\t' in sep:
        splitre = re.compile(r'\s*\t\s*')
    else:
        splitre = re.compile(r'\s{2,}|\t')

    tokre = re.compile(r"[A-Za-z0-9.,'|]{1,16}")
    okchars = set("0123456789OoDQlIiSsBZzGb.,'")

    def plausible(t):
        t2 = re.sub(r'\s*pcs$', '', t.strip())
        if not tokre.fullmatch(t2):
            return False
        bad = sum(1 for ch in t2 if ch not in okchars)
        return bad <= 2 and any(ch in okchars for ch in t2)

    sections = []
    cur = None
    total_tok = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith('MANIFEST') or s.startswith('COLUMNS'):
            continue
        if re.match(r'^==+\s*SECTION', s):
            cur = {"tokens": [], "sub": None}
            sections.append(cur)
            continue
        if s.startswith('SUBTOTAL'):
            if cur is None:
                cur = {"tokens": [], "sub": None}
                sections.append(cur)
            cur["sub"] = s[8:].strip()
            continue
        if s.startswith('TOTAL'):
            m = re.match(r'^TOTAL\s+(.*?)\s+ITEMS\s+(.*)$', s)
            if m:
                total_tok = m.group(1).strip()
            else:
                total_tok = s[5:].strip()
            continue
        toks = [t.strip() for t in splitre.split(s) if t.strip()]
        if not toks or not all(plausible(t) for t in toks):
            continue
        if cur is None:
            cur = {"tokens": [], "sub": None}
            sections.append(cur)
        cur["tokens"].extend(toks)

    lookd = set("0123456789OoDQlIiSsBZzGb")

    def norm_digits(t):
        return ''.join(l2d.get(ch, ch) for ch in t if ch.isdigit() or ch in l2d)

    all_toks = [t for sec in sections for t in sec["tokens"]]
    pcs_count = sum(1 for t in all_toks if t.endswith('pcs'))

    def type_cost(t, col):
        has_pcs = t.endswith('pcs')
        core = re.sub(r'\s*pcs$', '', t)
        if col == 'CODE':
            if has_pcs:
                return 4.0
            if len(core) < 6 or len(core) > 9:
                return 3.0
            a, b = core[0], core[1]
            lt = sum(1 for ch in (a, b) if ch.isalpha() or ch in '015826')
            rest = core[2:]
            dg = sum(1 for ch in rest if ch in lookd)
            c = (2 - lt) * 1.5 + (len(rest) - dg) * 1.0
            if a.isalpha() and b.isalpha():
                c -= 0.5
            if len(core) != 7:
                c += 0.5
            if any(ch in ".,'" for ch in core):
                c += 2.0
            return max(c, 0.0)
        if col == 'QTY':
            c = 0.0
            if pcs_count >= 2 and not has_pcs:
                c += 1.0
            if has_pcs:
                c -= 0.5
            if any(ch in ".,'" for ch in core):
                c += 2.5
            nd = norm_digits(core)
            if len(nd) != len(core):
                c += 2.0
            if len(nd) == 0:
                c += 3.0
            elif len(nd) > 4:
                c += 2.0
            elif len(nd) == 4:
                c += 0.7
            if core[:2].isalpha():
                c += 2.0
            return max(c, 0.0)
        if has_pcs:
            return 4.0
        c = 0.0
        nd = norm_digits(core)
        if len(nd) + sum(1 for ch in core if ch in ".,'") != len(core):
            c += 2.0
        if not any(ch in ".,'" for ch in core):
            c += 0.6 if len(nd) >= 3 else 1.5
        if core[:2].isalpha():
            c += 2.0
        return c

    DROP = 4.0
    for sec in sections:
        toks = sec["tokens"]
        n = len(toks)
        INF = 1e18
        dp = [[INF] * 4 for _ in range(n + 1)]
        bk = [[None] * 4 for _ in range(n + 1)]
        dp[0][0] = 0.0
        for i in range(n):
            for p in range(4):
                v = dp[i][p]
                if v >= INF:
                    continue
                w = v + type_cost(toks[i], order[p])
                np_ = (p + 1) % 4
                if w < dp[i + 1][np_]:
                    dp[i + 1][np_] = w
                    bk[i + 1][np_] = (p, 1)
                w = v + DROP
                if w < dp[i + 1][p]:
                    dp[i + 1][p] = w
                    bk[i + 1][p] = (p, 0)
        assign = []
        p = 0
        i = n
        while i > 0:
            pp, used = bk[i][p]
            if used:
                assign.append((i - 1, pp))
            p = pp
            i -= 1
        assign.reverse()
        rows = []
        currow = {}
        for idx, pcol in assign:
            currow[order[pcol]] = toks[idx]
            if pcol == 3:
                rows.append(currow)
                currow = {}
        sec["rows"] = rows

    money_toks = []
    for sec in sections:
        for r in sec["rows"]:
            money_toks.append(r.get('UNIT', ''))
            money_toks.append(r.get('AMOUNT', ''))
        if sec["sub"]:
            money_toks.append(sec["sub"])
    if total_tok:
        money_toks.append(total_tok)
    n_comma = 0
    n_dot = 0
    n_apos = 0
    for t in money_toks:
        if re.search(r',\w\w$', t):
            n_comma += 1
        if re.search(r'\.\w\w$', t):
            n_dot += 1
        n_apos += t.count("'")
    mark = ',' if n_comma > n_dot else '.'
    grouped = n_apos > 0
    em = re.escape(mark)
    if grouped:
        validre = re.compile(r"(0|[1-9]\d{0,2}('\d{3})*)" + em + r"\d\d")
    else:
        validre = re.compile(r"(0|[1-9]\d*)" + em + r"\d\d")

    def fmt(cents):
        ip = cents // 100
        dp_ = cents % 100
        s = str(ip)
        if grouped:
            parts = []
            while len(s) > 3:
                parts.append(s[-3:])
                s = s[:-3]
            parts.append(s)
            s = "'".join(reversed(parts))
        return s + mark + ('%02d' % dp_)

    def norm_money(t):
        out = []
        for ch in t:
            if ch.isdigit():
                out.append(ch)
            elif ch in '.,':
                out.append(mark)
            elif ch == "'":
                out.append(ch)
            elif ch in l2d:
                out.append(l2d[ch])
        return ''.join(out)

    def digits_val(s):
        d = ''.join(ch for ch in s if ch.isdigit())
        return int(d) if d else None

    def money_cands(tok):
        O = norm_money(tok)
        res = {}
        if not O:
            return O, res
        bases = [(O, 0)]
        if mark not in O and len(O) >= 2:
            bases.append((O[:-2] + mark + O[-2:], 1))
        for s, c in bases:
            if validre.fullmatch(s):
                v = digits_val(s)
                if v is not None and (v not in res or res[v] > c):
                    res[v] = c
            for e in _digit_edits(s, rev):
                if validre.fullmatch(e):
                    v = digits_val(e)
                    if v is not None and (v not in res or res[v] > c + 1):
                        res[v] = c + 1
        return O, res

    mcache = {}

    def money_cost(v, O, cands):
        if v in cands:
            return cands[v]
        if v < 0:
            return 50.0
        key = (v, O)
        if key in mcache:
            return mcache[key]
        c = _align_cost(fmt(v), O, conf)
        mcache[key] = c
        return c

    def qty_norm(t):
        core = re.sub(r'\s*pcs$', '', t.strip())
        return ''.join(l2d.get(ch, ch) for ch in core if ch.isdigit() or ch in l2d)

    def qty_cands(D):
        res = {}
        if D and D[0] != '0' and len(D) <= 3 and 1 <= int(D) <= 500:
            res[int(D)] = 0
        for e in _digit_edits(D, rev) if D else [str(k) for k in range(1, 10)]:
            if e and e[0] != '0' and len(e) <= 3:
                v = int(e)
                if 1 <= v <= 500 and v not in res:
                    res[v] = 1
        return res

    def qty_cost(q, D, cands):
        if q in cands:
            return cands[q]
        if q < 1 or q > 500:
            return 50.0
        return _align_cost(str(q), D, conf)

    def code_fix(t):
        core = ''.join(ch for ch in t if not ch.isspace())
        if len(core) < 2:
            return 'AA00000'
        lets = ''
        for ch in core[:2]:
            if ch in d2l:
                lets += d2l[ch]
            elif ch.isalpha():
                lets += ch.upper()
            else:
                lets += 'A'
        D = ''.join(l2d.get(ch, ch) for ch in core[2:] if ch.isdigit() or ch in l2d)
        if _check_ok(lets, D):
            return lets + D
        lvl = [D]
        seen = {D}
        for depth in range(2):
            nxt = []
            for s in lvl:
                for e in _digit_edits(s, rev):
                    if e in seen:
                        continue
                    seen.add(e)
                    if _check_ok(lets, e):
                        return lets + e
                    if len(e) <= 7:
                        nxt.append(e)
            lvl = nxt
            if depth == 0 and len(lvl) > 400:
                lvl = lvl[:400]
        D2 = (D + '00000')[:5]
        return lets + D2

    MAXOPT = 25

    def row_options(r):
        D = qty_norm(r.get('QTY', ''))
        Q = qty_cands(D)
        Uo, U = money_cands(r.get('UNIT', ''))
        Ao, A = money_cands(r.get('AMOUNT', ''))
        opts = {}

        def add(q, u, a, c):
            k = (q, u)
            if k not in opts or opts[k][0] > c:
                opts[k] = (c, a)

        Qi = list(Q.items())
        for a, ca in A.items():
            if a <= 0:
                continue
            for q, cq in Qi:
                if a % q == 0:
                    u = a // q
                    cu = U.get(u)
                    if cu is not None:
                        add(q, u, a, ca + cq + cu)
        q0s = [q for q, c in Qi if c == 0]
        u0s = [u for u, c in U.items() if c == 0]
        a0s = [a for a, c in A.items() if c == 0]
        for q in q0s:
            for u in u0s:
                a = q * u
                add(q, u, a, min(money_cost(a, Ao, A), 4.0) + 0.5)
            for a in a0s:
                if a % q == 0 and a > 0:
                    u = a // q
                    add(q, u, a, min(money_cost(u, Uo, U), 4.0) + 0.5)
        for u in u0s:
            for a in a0s:
                if u > 0 and a % u == 0:
                    q = a // u
                    if 1 <= q <= 500:
                        add(q, u, a, min(qty_cost(q, D, Q), 4.0) + 0.5)
        if not opts:
            qg = q0s[0] if q0s else (min(Q, key=lambda k: Q[k]) if Q else 1)
            ug = u0s[0] if u0s else (min(U, key=lambda k: U[k]) if U else (digits_val(Uo) or 0))
            add(qg, ug, qg * ug, 9.0)
        lst = sorted(((c, q, u, a) for (q, u), (c, a) in opts.items()),
                     key=lambda x: (x[0], x[1], x[2]))
        return {"opts": lst[:MAXOPT], "D": D, "Q": Q, "Uo": Uo, "U": U, "Ao": Ao, "A": A}

    sec_infos = []
    for sec in sections:
        sec_infos.append([row_options(r) for r in sec["rows"]])

    def sec_solve(ros, subtok):
        choice = [ro["opts"][0] for ro in ros]
        if subtok:
            So, SD = money_cands(subtok)
        else:
            So, SD = '', {}

        def subcost(s):
            if not subtok:
                return 0.0
            return min(money_cost(s, So, SD), 3.5)

        base_rows = sum(c[0] for c in choice)
        s = sum(c[3] for c in choice)
        best = base_rows + subcost(s)
        hyps = [(best, s, list(choice))]
        if best == base_rows and (not subtok or subcost(s) == 0):
            return hyps
        if time.process_time() - t0 > 0.75:
            return hyps
        for i, ro in enumerate(ros):
            c0 = choice[i]
            for o in ro["opts"][1:]:
                lb = base_rows - c0[0] + o[0]
                if lb >= best + 1.0:
                    continue
                s2 = s - c0[3] + o[3]
                tot = lb + subcost(s2)
                if tot < best + 1.0:
                    ch = list(choice)
                    ch[i] = o
                    hyps.append((tot, s2, ch))
        if subtok and SD and time.process_time() - t0 < 0.7:
            for S, cS in sorted(SD.items(), key=lambda x: x[1]):
                if time.process_time() - t0 > 0.7:
                    break
                for i, ro in enumerate(ros):
                    c0 = choice[i]
                    rest = base_rows - c0[0] + cS
                    a = S - (s - c0[3])
                    if a <= 0 or a == c0[3]:
                        continue
                    if rest >= best:
                        continue
                    ca = money_cost(a, ro["Ao"], ro["A"])
                    if rest + ca >= best + 1.0:
                        continue
                    for q, cq in ro["Q"].items():
                        if a % q:
                            continue
                        u = a // q
                        cu = ro["U"].get(u)
                        if cu is None:
                            if cq != 0:
                                continue
                            cu = money_cost(u, ro["Uo"], ro["U"])
                        tot = rest + ca + cq + cu
                        if tot < best + 1.0:
                            ch = list(choice)
                            ch[i] = (ca + cq + cu, q, u, a)
                            hyps.append((tot, S, ch))
        hyps.sort(key=lambda h: h[0])
        return hyps[:8]

    sec_hyps = []
    for k, sec in enumerate(sections):
        ros = sec_infos[k]
        if not ros:
            sec_hyps.append([(0.0, 0, [])])
            continue
        sec_hyps.append(sec_solve(ros, sec["sub"]))

    sel = [0] * len(sec_hyps)
    if total_tok and sec_hyps:
        To, TD = money_cands(total_tok)

        def tcost(v):
            return min(money_cost(v, To, TD), 3.5)

        def evalsel(sl):
            c = 0.0
            sm = 0
            for k, h in enumerate(sec_hyps):
                c += h[sl[k]][0]
                sm += h[sl[k]][1]
            return c + tcost(sm)

        bestc = evalsel(sel)
        improved = True
        rounds = 0
        while improved and rounds < 10:
            improved = False
            rounds += 1
            for k, h in enumerate(sec_hyps):
                for j in range(len(h)):
                    if j == sel[k]:
                        continue
                    sl = list(sel)
                    sl[k] = j
                    c = evalsel(sl)
                    if c < bestc - 1e-9:
                        bestc = c
                        sel = sl
                        improved = True

    items = []
    for k, sec in enumerate(sections):
        h = sec_hyps[k][sel[k]]
        for ri, r in enumerate(sec["rows"]):
            o = h[2][ri] if ri < len(h[2]) else sec_infos[k][ri]["opts"][0]
            items.append({"code": code_fix(r.get('CODE', '')), "qty": int(o[1]),
                          "unit_cents": int(o[2])})
    state["output"] = {"items": items}
    return state

import re
import time

LOOK_L2D = {"O": "0", "l": "1", "S": "5", "B": "8", "Z": "2", "G": "6", "I": "1", "o": "0"}
D2L = {"0": "O", "1": "I", "5": "S", "8": "B", "2": "Z", "6": "G"}
MISREAD = {"0": "68", "1": "74", "2": "7", "3": "89", "4": "91", "5": "63", "6": "50", "7": "12", "8": "30", "9": "43"}
DLOOK = {"0": "O", "1": "l", "5": "S", "8": "B", "2": "Z", "6": "G"}


def _rev_misread():
    r = {}
    for o, shows in MISREAD.items():
        for s in shows:
            r.setdefault(s, []).append((o, 0.0 if len(shows) == 1 else 0.05))
    return r


REV = _rev_misread()
TOKEN_RE = re.compile(r"[A-Z0-9]{0,2}[0-9OlSBZGIo.,']*( ?pcs)?")


def damage_cost(true_s, obs):
    n, m = len(true_s), len(obs)
    INF = 99.0
    dp = [[INF] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        row = dp[i]
        for j in range(m + 1):
            c = row[j]
            if c >= INF:
                continue
            if i < n:
                t = true_s[i]
                isd = t.isdigit()
                dc = 1.0 if (isd or t in ".,") else 3.0
                if dp[i + 1][j] > c + dc:
                    dp[i + 1][j] = c + dc
                if j < m:
                    o = obs[j]
                    if o == t:
                        sc = 0.0
                    elif isd and (DLOOK.get(t) == o or o in MISREAD[t]):
                        sc = 1.0
                    else:
                        sc = 3.0
                    if dp[i + 1][j + 1] > c + sc:
                        dp[i + 1][j + 1] = c + sc
                    if isd and j + 1 < m and obs[j] == t and obs[j + 1] == t:
                        if dp[i + 1][j + 2] > c + 1.0:
                            dp[i + 1][j + 2] = c + 1.0
            if j < m:
                if dp[i][j + 1] > c + 3.0:
                    dp[i][j + 1] = c + 3.0
    return dp[n][m]


def normalize_num(tok):
    cost = 0
    out = []
    for ch in tok:
        if ch in LOOK_L2D:
            out.append(LOOK_L2D[ch])
            cost += 1
        elif ch.isdigit() or ch in ".,":
            out.append(ch)
    return "".join(out), cost


def gen1(s, allow_mark):
    res = []
    L = len(s)
    for i, ch in enumerate(s):
        if ch.isdigit():
            for o, pen in REV.get(ch, []):
                res.append((s[:i] + o + s[i + 1:], 1.0 + pen))
            if i > 0 and s[i - 1] == ch:
                res.append((s[:i] + s[i + 1:], 1.0))
    for i in range(L + 1):
        for d in "0123456789":
            res.append((s[:i] + d + s[i:], 1.02))
    if allow_mark and "." not in s:
        for i in range(1, L):
            res.append((s[:i] + "." + s[i:], 1.0))
    return res


def parse_money_str(s):
    if s.count(".") != 1:
        return None
    a, b = s.split(".")
    if len(b) != 2 or not a or not a.isdigit() or not b.isdigit():
        return None
    if len(a) > 1 and a[0] == "0":
        return None
    return int(a) * 100 + int(b)


def parse_qty_str(s):
    if not s or not s.isdigit() or s[0] == "0":
        return None
    v = int(s)
    if 1 <= v <= 500:
        return v
    return None


def money_cands(tok):
    s, c0 = normalize_num(tok)
    s = s.replace(",", ".")
    out = {}
    v = parse_money_str(s)
    if v is not None:
        out[v] = float(c0)
    for s2, c in gen1(s, True):
        v = parse_money_str(s2)
        if v is not None and v > 0:
            cc = c0 + c
            if out.get(v, 99) > cc:
                out[v] = cc
    return out


def qty_cands(tok):
    t = re.sub(r"\s*pcs\s*$", "", tok)
    s, c0 = normalize_num(t)
    s = s.replace(",", "").replace(".", "")
    out = {}
    v = parse_qty_str(s)
    if v is not None:
        out[v] = float(c0)
    for s2, c in gen1(s, False):
        v = parse_qty_str(s2)
        if v is not None:
            cc = c0 + c
            if out.get(v, 99) > cc:
                out[v] = cc
    return out


def code_ok(letters, d):
    if len(d) != 5 or not d.isdigit():
        return False
    p1 = ord(letters[0]) - 64
    p2 = ord(letters[1]) - 64
    s = int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + p1 + p2
    return s % 10 == int(d[4])


def solve_code(tok):
    tok = tok.strip()
    tok = re.sub(r"[^A-Za-z0-9]", "", tok)
    if len(tok) < 2:
        return "AA00000"
    letters = ""
    for ch in tok[:2]:
        if ch in D2L:
            letters += D2L[ch]
        elif ch.isalpha():
            letters += ch.upper()
        else:
            letters += "A"
    dpart = ""
    for ch in tok[2:]:
        if ch in LOOK_L2D:
            dpart += LOOK_L2D[ch]
        elif ch.isdigit():
            dpart += ch
    if code_ok(letters, dpart):
        return letters + dpart
    level = [(dpart, 0.0)]
    seen = {dpart: 0.0}
    for depth in range(3):
        best = None
        nxt = []
        for s, c in level:
            for s2, c2 in gen1(s, False):
                cc = c + c2
                if len(s2) > 8:
                    continue
                if s2 in seen and seen[s2] <= cc:
                    continue
                seen[s2] = cc
                nxt.append((s2, cc))
                if len(s2) == 5 and code_ok(letters, s2):
                    if best is None or cc < best[0]:
                        best = (cc, s2)
        if best is not None:
            return letters + best[1]
        level = nxt
        if len(level) > 3000:
            break
    d = (dpart + "00000")[:5]
    return letters + d


def fmt_money(v, mark, grouped):
    a, b = divmod(v, 100)
    s = str(a)
    if grouped and len(s) > 3:
        parts = []
        while len(s) > 3:
            parts.insert(0, s[-3:])
            s = s[:-3]
        parts.insert(0, s)
        s = "'".join(parts)
    return s + mark + ("%02d" % b)


def node_parse(state, params):
    t0 = time.perf_counter()
    text = state["input"].get("text", "")
    lines = text.split("\n")
    sep = " | "
    order = ["CODE", "QTY", "UNIT", "AMOUNT"]
    for ln in lines:
        if ln.startswith("COLUMNS:"):
            body = ln[len("COLUMNS:"):]
            pos = []
            for nm in ["CODE", "QTY", "UNIT", "AMOUNT"]:
                pos.append((body.find(nm), nm))
            if all(p >= 0 for p, _ in pos):
                order = [nm for _, nm in sorted(pos)]
            if "|" in body:
                sep = " | "
            elif ";" in body:
                sep = ";"
            elif "\t" in body:
                sep = "\t"
            else:
                sep = "   "
            break

    def split(ln):
        if sep == " | ":
            parts = ln.split("|")
        elif sep == ";":
            parts = ln.split(";")
        elif sep == "\t":
            parts = ln.split("\t")
        else:
            parts = re.split(r" {2,}|\t", ln)
        return [p.strip() for p in parts if p.strip()]

    sections = []
    cur = None
    total_tok = None
    for ln in lines:
        s = ln.strip()
        if not s:
            continue
        if s.startswith("MANIFEST") or s.startswith("COLUMNS:"):
            continue
        if re.match(r"^==\s*SECTION", s):
            cur = {"tokens": [], "sub": None}
            sections.append(cur)
            continue
        m = re.match(r"^SUBTOTAL\s+(.*)$", s)
        if m:
            if cur is None:
                cur = {"tokens": [], "sub": None}
                sections.append(cur)
            cur["sub"] = m.group(1).strip()
            cur = None
            continue
        m = re.match(r"^TOTAL\s+(.*?)\s+ITEMS\s*(.*)$", s)
        if m:
            total_tok = [m.group(1).strip(), m.group(2).strip()]
            continue
        toks = split(ln)
        if not toks:
            continue
        ok = True
        for tk in toks:
            if not TOKEN_RE.fullmatch(tk) or not re.search(r"[0-9OlSBZG]", tk):
                ok = False
                break
        if not ok:
            continue
        if cur is None:
            cur = {"tokens": [], "sub": None}
            sections.append(cur)
        cur["tokens"].extend(toks)

    mtoks = []
    pcs = 0
    for sec in sections:
        for t in sec["tokens"]:
            mtoks.append(t)
            if "pcs" in t:
                pcs += 1
        if sec["sub"]:
            mtoks.append(sec["sub"])
    dots = sum(t.count(".") for t in mtoks)
    commas = sum(t.count(",") for t in mtoks)
    apos = sum(t.count("'") for t in mtoks)
    state["style"] = {"mark": "," if commas > dots else ".", "grouped": apos > 0, "pcs": pcs > 0}
    state["sep"] = sep
    state["order"] = order
    state["sections"] = sections
    state["total_tok"] = total_tok
    state["t0"] = t0
    return state


def type_cost(tok, col):
    t = tok.strip()
    if col == "CODE":
        if re.fullmatch(r"[A-Z0-9]{2}[0-9OlSBZGI]{3,7}", t) and re.match(r"[A-Z]", t):
            return 0.0
        if re.fullmatch(r"[A-Z0-9]{2}[0-9OlSBZGI]{3,7}", t):
            return 0.5
        return 3.0
    if col == "QTY":
        if "pcs" in t:
            return 0.0
        if re.search(r"[A-Z]{2}", t[:2]) or re.search(r"[A-Z]", t[:1]):
            return 3.0
        if "." in t or "," in t:
            return 2.0
        if len(re.sub(r"\D", "", t)) <= 3:
            return 0.0
        return 1.0
    if "pcs" in t:
        return 3.0
    if re.match(r"[A-Z]{2}", t):
        return 3.0
    if "." in t or "," in t:
        return 0.0
    return 0.8


def align(tokens, order):
    n = len(tokens)
    if n % 4 == 0:
        ok = True
        for i, t in enumerate(tokens):
            if type_cost(t, order[i % 4]) >= 3.0:
                ok = False
                break
        if ok:
            return [tokens[i:i + 4] for i in range(0, n, 4)]
    INF = 1e9
    SKIP = 3.5
    MISS = 4.0
    dp = [[INF] * 4 for _ in range(n + 1)]
    bk = [[None] * 4 for _ in range(n + 1)]
    dp[0][0] = 0.0
    for i in range(n + 1):
        for _ in range(2):
            for c in range(4):
                if dp[i][c] < INF:
                    nc = (c + 1) % 4
                    if dp[i][nc] > dp[i][c] + MISS:
                        dp[i][nc] = dp[i][c] + MISS
                        bk[i][nc] = ("miss", i, c)
        if i == n:
            break
        for c in range(4):
            v = dp[i][c]
            if v >= INF:
                continue
            tc = type_cost(tokens[i], order[c])
            nc = (c + 1) % 4
            if dp[i + 1][nc] > v + tc:
                dp[i + 1][nc] = v + tc
                bk[i + 1][nc] = ("take", i, c)
            if dp[i + 1][c] > v + SKIP:
                dp[i + 1][c] = v + SKIP
                bk[i + 1][c] = ("skip", i, c)
    seq = []
    i, c = n, 0
    guard = 0
    while (i, c) != (0, 0) and guard < 10 * (n + 4):
        guard += 1
        b = bk[i][c]
        if b is None:
            break
        kind, pi, pc = b
        if kind == "take":
            seq.append(tokens[pi])
        elif kind == "miss":
            seq.append("")
        i, c = pi, pc
    seq.reverse()
    rows = []
    for k in range(0, len(seq) - len(seq) % 4, 4):
        rows.append(seq[k:k + 4])
    return rows


def solve_row(code_t, qty_t, unit_t, amt_t, style, deadline):
    mark, grouped = style["mark"], style["grouped"]
    Q = qty_cands(qty_t) if qty_t else {}
    U = money_cands(unit_t) if unit_t else {}
    A = money_cands(amt_t) if amt_t else {}
    sols = {}

    def add(q, u, a, c):
        key = (q, u)
        if key not in sols or sols[key][0] > c:
            sols[key] = (c, a)

    qtok = re.sub(r"\s*pcs\s*$", "", qty_t)

    def dq(q):
        return damage_cost(str(q), qtok) if qtok else 4.0

    def du(u):
        return damage_cost(fmt_money(u, mark, grouped), unit_t) if unit_t else 4.0

    def da(a):
        return damage_cost(fmt_money(a, mark, grouped), amt_t) if amt_t else 4.0

    for q, cq in Q.items():
        for u, cu in U.items():
            a = q * u
            ca = A.get(a)
            if ca is not None:
                add(q, u, a, cq + cu + ca)

    def anchors(D):
        it = sorted(D.items(), key=lambda kv: kv[1])
        return [kv for kv in it[:3] if kv[1] <= it[0][1] + 0.5] if it else []

    aq, au, aa = anchors(Q), anchors(U), anchors(A)
    for q, cq in aq:
        for u, cu in au:
            a = q * u
            add(q, u, a, cq + cu + da(a))
    for q, cq in aq:
        for a, ca in aa:
            if a % q == 0 and a > 0:
                u = a // q
                add(q, u, a, cq + ca + du(u))
    for u, cu in au:
        for a, ca in aa:
            if u > 0 and a % u == 0:
                q = a // u
                if 1 <= q <= 500:
                    add(q, u, a, cu + ca + dq(q))
    best = min((v[0] for v in sols.values()), default=99)
    if best > 2.1 and time.perf_counter() < deadline:
        cnt = 0
        for q, cq in Q.items():
            for a, ca in A.items():
                if a % q == 0 and cq + ca < 2.1:
                    u = a // q
                    cnt += 1
                    if cnt > 400:
                        break
                    add(q, u, a, cq + ca + du(u))
        cnt = 0
        for u, cu in U.items():
            for a, ca in A.items():
                if a % u == 0 and cu + ca < 2.1:
                    q = a // u
                    if 1 <= q <= 500:
                        cnt += 1
                        if cnt > 400:
                            break
                        add(q, u, a, cu + ca + dq(q))
    lst = sorted(((v[0], k[0], k[1], v[1]) for k, v in sols.items()))
    if not lst:
        q = min(Q.items(), key=lambda kv: kv[1])[0] if Q else 1
        u = min(U.items(), key=lambda kv: kv[1])[0] if U else 0
        lst = [(50.0, q, u, q * u)]
    return lst[:6]


def node_solve(state, params):
    t0 = state.get("t0", time.perf_counter())
    deadline = t0 + 0.75
    style = state["style"]
    order = state["order"]
    items = []
    for sec in state["sections"]:
        rows = align(sec["tokens"], order)
        sols = []
        codes = []
        for r in rows:
            f = dict(zip(order, r))
            codes.append(solve_code(f.get("CODE", "")) if f.get("CODE") else "AA00000")
            sols.append(solve_row(f.get("CODE", ""), f.get("QTY", ""), f.get("UNIT", ""), f.get("AMOUNT", ""), style, deadline))
        choice = [0] * len(sols)
        if sec.get("sub") and sols:
            SC = money_cands(sec["sub"])

            def subc(S):
                return SC.get(S, 2.5)

            S = sum(s[0][3] for s in sols)
            base = sum(s[0][0] for s in sols) + subc(S)
            bestc, bestsw = base, None
            for ri, s in enumerate(sols):
                for k in range(1, len(s)):
                    S2 = S - s[0][3] + s[k][3]
                    c = base - subc(S) - s[0][0] + s[k][0] + subc(S2)
                    if c < bestc - 1e-9:
                        bestc, bestsw = c, (ri, k)
            if bestsw:
                choice[bestsw[0]] = bestsw[1]
        for i, s in enumerate(sols):
            c, q, u, a = s[choice[i]]
            items.append({"code": codes[i], "qty": int(q), "unit_cents": int(u)})
    state["output"] = {"items": items}
    return state

import re
import time

MIS = {'0': '68', '1': '74', '2': '7', '3': '89', '4': '91', '5': '63', '6': '50', '7': '12', '8': '30', '9': '43'}
L2D = {'O': '0', 'l': '1', 'S': '5', 'B': '8', 'Z': '2', 'G': '6', 'I': '1', 'o': '0', 'L': '1', 's': '5', 'b': '8', 'z': '2', 'g': '6', 'i': '1', '|': '1'}
D2L = {'0': 'O', '1': 'I', '5': 'S', '8': 'B', '2': 'Z', '6': 'G', '3': 'B', '4': 'A', '7': 'T', '9': 'G'}


def _rev():
    r = {}
    for k, v in MIS.items():
        for c in v:
            r.setdefault(c, []).append(k)
    return r


def _make_dist():
    memo = {}

    def dist(t, o):
        key = (t, o)
        r = memo.get(key)
        if r is not None:
            return r
        n = len(t)
        m = len(o)
        INF = 1e9
        D = [[INF] * (m + 1) for _ in range(n + 1)]
        D[0][0] = 0.0
        for i in range(n + 1):
            Di = D[i]
            for j in range(m + 1):
                cur = Di[j]
                if cur >= INF:
                    continue
                if j < m:
                    oj = o[j]
                    if cur + 3 < Di[j + 1]:
                        Di[j + 1] = cur + 3
                if i < n:
                    ti = t[i]
                    Dn = D[i + 1]
                    if j < m:
                        if ti == oj:
                            c = cur
                        elif ti in MIS and oj in MIS[ti]:
                            c = cur + 1
                        else:
                            c = cur + 3
                        if c < Dn[j + 1]:
                            Dn[j + 1] = c
                        if j + 1 < m and oj == ti and o[j + 1] == ti:
                            if cur + 1 < Dn[j + 2]:
                                Dn[j + 2] = cur + 1
                    c = cur + (1 if ti != '.' else 0.9)
                    if c < Dn[j]:
                        Dn[j] = c
        r = D[n][m]
        memo[key] = r
        return r
    return dist


def fmt(c):
    return "%d.%02d" % (c // 100, c % 100)


def norm_digits(s):
    return ''.join(L2D.get(ch, ch) for ch in s)


def edits1(s, REV):
    out = set()
    for j, ch in enumerate(s):
        if ch in REV:
            for x in REV[ch]:
                out.add(s[:j] + x + s[j + 1:])
        if j + 1 < len(s) and s[j + 1] == ch and ch != '.':
            out.add(s[:j] + s[j + 1:])
    for j in range(len(s) + 1):
        for x in '0123456789':
            out.add(s[:j] + x + s[j:])
    if '.' not in s and len(s) >= 3:
        out.add(s[:-2] + '.' + s[-2:])
    return out


def money_val(s):
    if s.count('.') > 1:
        return None
    if '.' in s:
        a, b = s.split('.')
        if len(b) != 2 or not a.isdigit() or not b.isdigit():
            return None
        return int(a) * 100 + int(b)
    if not s.isdigit():
        return None
    return int(s)


def solve(state, params):
    t0 = time.process_time()
    REV = _rev()
    dist = _make_dist()
    text = state.get("input", {}).get("text", "") or ""
    lines = text.split("\n")

    sep = ';'
    order = ['CODE', 'QTY', 'UNIT', 'AMOUNT']
    for ln in lines:
        if 'COLUMNS' in ln:
            rest = ln.split('COLUMNS', 1)[1]
            rest = rest[1:] if rest.startswith(':') else rest
            names = re.findall(r'CODE|QTY|UNIT|AMOUNT', rest)
            if len(names) == 4 and len(set(names)) == 4:
                order = names
            body = rest.strip(' ')
            if '|' in body:
                sep = '|'
            elif ';' in body:
                sep = ';'
            elif '\t' in body:
                sep = '\t'
            else:
                sep = '   '
            break

    def split_line(ln):
        if sep == '|':
            parts = ln.split('|')
        elif sep == ';':
            parts = ln.split(';')
        elif sep == '\t':
            parts = ln.split('\t')
        else:
            parts = re.split(r' {2,}|\t', ln)
        return [p.strip() for p in parts if p.strip() != '']

    noise_re = re.compile(r'[-=#*()\[\]:/!?_~<>@&%$+"]')

    def is_noise(ln):
        s = ln.strip()
        if not s:
            return True
        if noise_re.search(s):
            return True
        s2 = s.replace('pcs', '')
        if re.search(r'[a-km-z]', s2):
            return True
        for run in re.findall(r'[A-Z]{5,}', s2):
            if sum(1 for ch in run if ch not in 'OSBZGI') >= 3:
                return True
        return False

    sections = []
    cur = None
    total_obs = None
    for ln in lines:
        if re.search(r'==\s*SECTION', ln):
            cur = {"tokens": [], "sub": None}
            sections.append(cur)
            continue
        m = re.search(r'SUBTOTAL\s+(.*)$', ln)
        if m:
            if cur is not None:
                cur["sub"] = m.group(1).strip()
                cur = None
            continue
        m = re.search(r'\bTOTAL\s+(.*?)(?:\s+ITEMS\s+(.*))?$', ln)
        if m and 'COLUMNS' not in ln:
            total_obs = m.group(1).strip()
            cur = None
            continue
        if 'MANIFEST' in ln or 'COLUMNS' in ln:
            continue
        if is_noise(ln):
            continue
        if cur is None:
            if not sections:
                cur = {"tokens": [], "sub": None}
                sections.append(cur)
            else:
                cur = sections[-1]
        cur["tokens"].extend(split_line(ln))

    alltok = [t for s in sections for t in s["tokens"]]
    ncomma = sum(1 for t in alltok if re.search(r'\d,\d\d$', t))
    ndot = sum(1 for t in alltok if re.search(r'\d\.\d\d$', t))
    dec = ',' if ncomma > ndot else '.'

    def norm_money(s):
        s = s.replace("'", "").replace(' ', '')
        if dec == ',':
            s = s.replace('.', '').replace(',', '.')
        else:
            s = s.replace(',', '')
        return norm_digits(s)

    def norm_qty(s):
        s = re.sub(r'\s*pcs\s*$', '', s.strip())
        return norm_digits(s.replace(' ', ''))

    code_re = re.compile(r'^[A-Z0-9lO|]{2}[0-9A-Za-z|]{3,7}$')
    qty_re = re.compile(r'^[0-9OlSBZGI]{1,4}(\s*pcs)?$')
    money_re = re.compile(r"^[0-9OlSBZGI'.,]{1,14}$")

    def tcost(tok, col):
        if col == 'CODE':
            if code_re.match(tok) and 'pcs' not in tok:
                return 0.0 if re.search(r'[A-Z]', tok[:2]) else 0.5
            return 5.0
        if col == 'QTY':
            if qty_re.match(tok):
                return 0.0 if ('.' not in tok and ',' not in tok) else 3.0
            return 5.0
        if money_re.match(tok):
            nt = norm_money(tok)
            if '.' in nt:
                return 0.0
            return 0.4 if len(nt) >= 3 else 1.5
        return 5.0

    def align(tokens):
        n = len(tokens)
        INF = 1e18
        best = [[INF] * 4 for _ in range(n + 1)]
        back = [[None] * 4 for _ in range(n + 1)]
        best[0][0] = 0.0
        for i in range(n):
            for ph in range(4):
                c = best[i][ph]
                if c >= INF:
                    continue
                nc = c + tcost(tokens[i], order[ph])
                np = (ph + 1) % 4
                if nc < best[i + 1][np]:
                    best[i + 1][np] = nc
                    back[i + 1][np] = (ph, 1)
                nc = c + 4.0
                if nc < best[i + 1][ph]:
                    best[i + 1][ph] = nc
                    back[i + 1][ph] = (ph, 0)
        endph = 0
        if best[n][0] >= INF:
            endph = min(range(4), key=lambda p: best[n][p])
        assign = []
        i, ph = n, endph
        while i > 0:
            pp, used = back[i][ph]
            assign.append((i - 1, pp if used else None))
            i -= 1
            ph = pp
        assign.reverse()
        rows = []
        currow = {}
        for idx, col in assign:
            if col is None:
                continue
            currow[order[col]] = tokens[idx]
            if col == 3:
                rows.append(currow)
                currow = {}
        if currow:
            rows.append(currow)
        return rows

    def check_ok(L, d):
        return (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + ord(L[0]) - 64 + ord(L[1]) - 64) % 10 == int(d[4])

    def fix_code(tok):
        tok = tok.strip().replace(' ', '')
        if len(tok) < 2:
            return "AA00000"
        L = ''
        for ch in tok[:2]:
            if ch.isdigit():
                L += D2L.get(ch, 'A')
            elif ch in 'l|':
                L += 'I'
            elif 'A' <= ch.upper() <= 'Z':
                L += ch.upper()
            else:
                L += 'A'
        ds = ''.join(ch for ch in norm_digits(tok[2:]) if ch.isdigit())
        if len(ds) == 5 and check_ok(L, ds):
            return L + ds
        frontier = {ds}
        seen = {ds}
        for depth in range(2):
            found = []
            nxt = set()
            for s in frontier:
                for e in edits1(s, REV):
                    if '.' in e or e in seen:
                        continue
                    seen.add(e)
                    nxt.add(e)
                    if len(e) == 5 and check_ok(L, e):
                        found.append((dist(e, ds), e))
            if found:
                found.sort()
                return L + found[0][1]
            frontier = nxt
            if len(frontier) > 20000:
                break
        d = ds[:4] if len(ds) >= 5 else (ds + '0000')[:4]
        chk = (int(d[0]) + 2 * int(d[1]) + 3 * int(d[2]) + 4 * int(d[3]) + ord(L[0]) - 64 + ord(L[1]) - 64) % 10
        return L + d + str(chk)

    qcache = {}

    def qcands(oq):
        r = qcache.get(oq)
        if r is not None:
            return r
        lst = []
        for q in range(1, 501):
            c = dist(str(q), oq)
            if c <= 2.5:
                lst.append((c, q))
        if not lst:
            lst = sorted((dist(str(q), oq), q) for q in range(1, 501))[:20]
        lst.sort()
        qcache[oq] = lst
        return lst

    mcache = {}

    def mcands(om, depth):
        key = (om, depth)
        r = mcache.get(key)
        if r is not None:
            return r
        strs = {om}
        frontier = {om}
        for _ in range(depth):
            nxt = set()
            for s in frontier:
                for e in edits1(s, REV):
                    if e not in strs:
                        strs.add(e)
                        nxt.add(e)
            frontier = nxt
        vals = {}
        for s in strs:
            v = money_val(s)
            if v is None or v <= 0 or v in vals:
                continue
            vals[v] = dist(fmt(v), om)
        lst = sorted((c, v) for v, c in vals.items())
        mcache[key] = lst
        return lst

    def solve_row(oq, ou, oa, margin, depth, cap):
        Qc = qcands(oq)
        Uc = mcands(ou, depth)
        Ac = mcands(oa, depth)
        sols = {}
        bestc = [1e9]

        def rec(q, u, c):
            if c < sols.get((q, u), 1e9):
                sols[(q, u)] = c
            if c < bestc[0]:
                bestc[0] = c
        for cq, q in Qc:
            if cq > bestc[0] + margin:
                break
            for cu, u in Uc:
                if cq + cu > bestc[0] + margin:
                    break
                rec(q, u, cq + cu + dist(fmt(q * u), oa))
            for ca, a in Ac:
                if cq + ca > bestc[0] + margin:
                    break
                if a % q:
                    continue
                u = a // q
                rec(q, u, cq + ca + dist(fmt(u), ou))
        lst = sorted((c, q, u) for (q, u), c in sols.items() if c <= bestc[0] + margin)
        return lst[:cap]

    sec_rows = []
    for s in sections:
        rows = align(s["tokens"])
        rr = []
        for r in rows:
            oq = norm_qty(r.get('QTY', '1'))
            ou = norm_money(r.get('UNIT', '0.00'))
            oa = norm_money(r.get('AMOUNT', '0.00'))
            code = fix_code(r.get('CODE', 'AA00000'))
            sl = []
            if time.process_time() - t0 < 0.6:
                sl = solve_row(oq, ou, oa, 0.0, 1, 5)
                if (not sl or sl[0][0] > 2.0) and time.process_time() - t0 < 0.5:
                    sl2 = solve_row(oq, ou, oa, 0.0, 2, 5)
                    if sl2 and (not sl or sl2[0][0] < sl[0][0]):
                        sl = sl2
            if not sl:
                qv = int(oq) if oq.isdigit() and 1 <= int(oq) <= 500 else 1
                uv = money_val(ou) or 0
                sl = [(9.0, qv, uv)]
            rr.append({"code": code, "oq": oq, "ou": ou, "oa": oa, "alts": sl, "sel": 0})
        sec_rows.append(rr)

    osubs = [norm_money(s["sub"]) if s["sub"] else None for s in sections]
    otot = norm_money(total_obs) if total_obs else None

    def row_amt(r):
        a = r["alts"][r["sel"]]
        return a[1] * a[2]

    def sec_cost(k, ssum):
        if osubs[k] is None:
            return 0.0
        return min(dist(fmt(ssum), osubs[k]), 4.0)

    def tot_cost(g):
        if otot is None:
            return 0.0
        return min(dist(fmt(g), otot), 4.0)

    sums = [sum(row_amt(r) for r in rr) for rr in sec_rows]
    for it in range(3):
        improved = False
        for k, rr in enumerate(sec_rows):
            if time.process_time() - t0 > 0.8:
                break
            base_sc = sec_cost(k, sums[k])
            g = sum(sums)
            base_tc = tot_cost(g)
            if base_sc == 0 and (base_tc == 0 or it == 0):
                continue
            for r in rr:
                if not r.get("wide") and time.process_time() - t0 < 0.7:
                    cur = r["alts"][r["sel"]]
                    alts = list(solve_row(r["oq"], r["ou"], r["oa"], 2.5, 1, 25))
                    if (cur[1], cur[2]) not in set((a[1], a[2]) for a in alts):
                        alts.append(cur)
                    alts.sort()
                    r["alts"] = alts
                    r["sel"] = [(a[1], a[2]) for a in alts].index((cur[1], cur[2]))
                    r["wide"] = True
            best_delta = 0.0
            best_mv = None
            cur_total = base_sc + base_tc
            for i, r in enumerate(rr):
                ca = r["alts"][r["sel"]]
                a0 = ca[1] * ca[2]
                for j, alt in enumerate(r["alts"]):
                    if j == r["sel"]:
                        continue
                    na = alt[1] * alt[2]
                    nt = sec_cost(k, sums[k] - a0 + na) + tot_cost(g - a0 + na)
                    delta = alt[0] - ca[0] + nt - cur_total
                    if delta < best_delta - 1e-9:
                        best_delta = delta
                        best_mv = [(i, j)]
            if best_mv is None and base_sc > 0 and time.process_time() - t0 < 0.75:
                n = len(rr)
                for i in range(n):
                    if time.process_time() - t0 > 0.85:
                        break
                    ri = rr[i]
                    ci = ri["alts"][ri["sel"]]
                    ai0 = ci[1] * ci[2]
                    for ji, alti in enumerate(ri["alts"][:10]):
                        if ji == ri["sel"]:
                            continue
                        di = alti[0] - ci[0]
                        if di >= cur_total:
                            continue
                        si = sums[k] - ai0 + alti[1] * alti[2]
                        for i2 in range(i + 1, n):
                            r2 = rr[i2]
                            c2 = r2["alts"][r2["sel"]]
                            a20 = c2[1] * c2[2]
                            for j2, alt2 in enumerate(r2["alts"][:10]):
                                if j2 == r2["sel"]:
                                    continue
                                d = di + alt2[0] - c2[0]
                                if d >= cur_total + best_delta:
                                    continue
                                ns = si - a20 + alt2[1] * alt2[2]
                                nt = sec_cost(k, ns) + tot_cost(g - sums[k] + ns)
                                delta = d + nt - cur_total
                                if delta < best_delta - 1e-9:
                                    best_delta = delta
                                    best_mv = [(i, ji), (i2, j2)]
            if best_mv:
                for i, j in best_mv:
                    rr[i]["sel"] = j
                sums[k] = sum(row_amt(r) for r in rr)
                improved = True
        if not improved:
            break

    items = []
    for rr in sec_rows:
        for r in rr:
            a = r["alts"][r["sel"]]
            items.append({"code": r["code"], "qty": int(a[1]), "unit_cents": int(a[2])})
    state["output"] = {"items": items}
    return state
